window.LAW_DATA = {"id": "tefl", "title": "قانون الطفل", "title_en": "CHILD LAW", "cat": "خاص", "icon": "👶", "desc": "القانون رقم 12 لسنة 1996 — حقوق الطفل ورعايته وحمايته القانونية.", "article_count": 166, "articles": [{"number": "الأولى", "chapter": "", "text": "يعمل بأحكام قانون الطفل المرافق ، ويلغى كل حكم يتعارض مع أحكامه ."}, {"number": "الثانية", "chapter": "", "text": "يصدر رئيس مجلس الوزراء اللائحة التنفيذية اللازمة لتنفيذ أحكام هذا القانون ."}, {"number": "الثالثة", "chapter": "", "text": "ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتبارا من اليوم التالى لتاريخ نشرة . يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها . صدر برئاسة الجمهورية فى 6 ذى القعدة سنة 1416 هـ . ( الموافق 25 مارس سنة 1996 م ) . حسنى مبارك قانون الطفل"}, {"number": "1", "chapter": "الباب الأول", "text": "تكفل الدولة حماية الطفولة والأمومة ، وترعى الأطفال ، وتعمل على تهيئة الظروف المناسبة لتنشئتهم التنشئة الصحيحة من كافة النواحى فى إطار من الحرية والكرامة الإنسانية . كما تكفل الدولة ، كحد أدنى ، حقوق الطفل الواردة باتفاقية حقوق الطفل وغيرها من المواثيق الدولية ذات الصلة النافذة فى مصر . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "2", "chapter": "الباب الأول", "text": "يقصد بالطفل فى مجال الرعاية المنصوص عليها فى هذا القانون كل من لم يتجاوز سنة الثامنة عشرة سنة ميلادية كاملة . وتثبت السن بموجب شهادة الميلاد أو بطاقة الرقم القومى أو أى مستند رسمى آخر . فإذا لم يوجد المستند الرسمى أصلا قدرت السن بمعرفة إحدى الجهات التى يصدر بتحديدها قرار من وزير العدل بالاتفاق مع وزير الصحة . مستبدلة بالقانون رقم 126 لسنة 2008."}, {"number": "3", "chapter": "الباب الأول", "text": "يكفل هذا القانون ، على وجه الخصوص ، المبادىء والحقوق الآتية : (أ)- حق الطفل فى الحياة والبقاء والنمو فى كنف أسرة متماسكة ومتضامنة وفى التمتع بمختلف التدابير الوقائية ، وحمايته من كافة أشكال العنف أو الضرر أو الإساءة البدنيه أو المعنوية أو الجنسية أو الإهمال أو التقصير أو غير ذلك من أشكال إساءة المعاملة والاستغلال . (ب)- الحماية من أى نوع من أنواع التمييز بين الأطفال ، بسبب محل الميلاد أو الوالدين ، أو الجنس أو الدين أو العنصر ، أو الإعاقة ، أو أى وضع آخر ، وتأمين المساواة الفعلية بينهم فى الانتفاع بكافة الحقوق . (ج) - حق الطفل القادر على تكوين آرائه الخاصة فى الحصول على المعلومات التى تمكنه من تكوين هذه الآراء وفى التعبير عنها ، والاستماع إلية فى جميع المسائل المتعلقة به ، بما فيها الإجراءات القضائية والإدارية ، وفقا للإجراءات التى يحددها القانون . وتكون لحماية الطفل ومصالحة الفضلى الأولوية فى جميع القرارات والإجراءات المتعلقة بالطفولة أيا كانت الجهة التى تصدرها أو تباشرها . مستبدلة بالقانون رقم 126 لسنة 2008."}, {"number": "4", "chapter": "الباب الأول", "text": "للطفل الحق فى نسبة إلى والدية الشرعيين والتمتع برعايتهما . وله الحق فى إثبات نسبة الشرعى إليهما بكافة وسائل الإثبات بما فيها الوسائل العلمية المشروعة . وعلى الوالدين أن يوفرا الرعاية والحماية الضرورية للطفل ، وعلى الدولة أن توفر رعاية بديلة لكل طفل حرم من رعاية أسرته ، ويحظر التبنى ."}, {"number": "5", "chapter": "الباب الأول", "text": "لكل طفل الحق فى أن يكون له اسم يميزه ، ويسجل هذا الاسم عند الميلاد فى سجلات المواليد وفقا لأحكام هذا القانون . ولا يجوز أن يكون الاسم منطويا على تحقير أو مهانة لكرامة الطفل أو منافيا للعقائد الدينية ."}, {"number": "6", "chapter": "الباب الأول", "text": "لكل طفل الحق فى أن تكون له جنسية وفقا لأحكام القانون الخاص بالجنسية المصرية ."}, {"number": "7", "chapter": "الباب الأول", "text": "يتمتع كل طفل بجميع الحقوق الشرعية وعلى الأخص حقه فى الرضاعة والحضانة والمأكل والملبس ورؤية والدية ورعاية أمواله ، وفقا للقوانين الخاصة بالأحوال الشخصية ."}, {"number": "7 مكرر", "chapter": "الباب الأول", "text": "لكل طفل الحق فى الحصول على خدمات الرعاية الصحية والاجتماعية وعلاج الأمراض ، وتتخذ الدولة كافة التدابير لضمان تمتع جميع الأطفال بأعلى مستوى ممكن من الصحة . وتكفل الدولة تزويد الوالدين والطفل وجميع قطاعات المجتمع بالمعلومات الأساسية المتعلقة بصحة الطفل وتغذيته ومزايا الرضاعة الطبيعية ومبادىء حفظ الصحة وسلامة البيئة والوقاية من الحوادث ، والمساعدة فى الإفادة من هذه المعلومات . كما تكفل الدولة للطفل ، فى جميع المجالات ، حقه فى بيئة صالحة وصحية ونظيفة ، واتخاذ جميع التدابير الفعالة لإلغاء الممارسات الضارة بصحته . مضافة بالقانون رقم 126 لسنة 2008."}, {"number": "7 مكرر", "chapter": "الباب الأول", "text": "أ) : مع مراعاة واجبات وحقوق متولى رعاية الطفل ، وحقه فى التأديب المباح شرعا ، يحظر تعريض الطفل عمداً لأى إيذاء بدنى ضار أو ممارسة ضارة أو غير مشروعة . وللجنة الفرعية لحماية الطفولة المختصة اتخاذ الإجراءات القانونية عند مخالفة نص الفقرة السابقة . مضافة بالقانون رقم 126 لسنة 2008."}, {"number": "7 مكرر", "chapter": "الباب الأول", "text": "ب) : تكفل الدولة أولوية الحفاظ على حياة الطفل وتنشئته تنشئة سالمة آمنة بعيدة عن النزاعات المسلحة ، وضمان عدم انخراطه فى الأعمال الحربية ، وتكفل احترام حقوقه فى حالات الطوارىء والكوارث والحروب والنزاعات المسلحة ، وتتخذ كافة التدابير لملاحقة ومعاقبة كل من يرتكب فى حق الطفل جريمة من جرائم الحرب أو الإبادة الجماعية أو من الجرائم ضد الإنسانية . مضافة بالقانون رقم 126 لسنة 2008."}, {"number": "8", "chapter": "الفصل الأول", "text": "لا يجوز لغير الأطباء البشريين مزاولة مهنة التوليد بأى صفة عامة كانت أو خاصة إلا لمن كان اسمها مقيدا بسجلات الموالدات أو مساعدات المولدات أو القابلات بوزارة الصحة ."}, {"number": "9", "chapter": "الفصل الأول", "text": "على من رخص لها بمزاولة مهنة التوليد أن تبلغ وزارة الصحة بخطاب موصى علية بأى تغيير دائم فى محل إقامتها خلال ثلاثين يوما من تاريخ هذا التغيير ، وإلا جاز لوزارة الصحة شطب اسمها من السجل المعد لذلك بعد خمسة عشر يوما من تاريخ إبلاغها خطاب موصى علية فى آخر عنوان معروف لها . ويجوز لمن شطب اسمها على الوجة المتقدم الحق فى إعادة قيد اسمها إذا أبلغت وزارة الصحة بعنوانها ، مقابل رسم إعادة قيد تحدده اللائحة التنفيذية بما لا يجاوز عشرة جنيهات ."}, {"number": "10", "chapter": "الفصل الأول", "text": "على من رخص لها مزاولة مهنة التوليد أن تلتزم فى مباشرة مهنتها بالواجبات التى يصدر بها قرار من وزير الصحة وإلا تعرضت للمساءلة التأديبية . ويشكل بكل محافظة بقرار من المحافظ مجلس لتأديب المرخص لهن بمزاولة مهنة التوليد من غير العاملين بالجهاز الادارى للدولة ، برئاسة مدير الشئون الصحية المختص وعضوية طبيب من قسم رعاية الأمومة والطفولة وأحد أعضاء الشئون القانونية بالمديرية . ولمجلس التأديب أن يقرر شطب اسم المرخص لها من السجل ، أو حرمانها من مزاولة المهنة لمدة لا تزيد على سنة لأمور تمس الاستقامة أو الشرف أو الكفاءة فى مهنتها أو أى مخالفة أخرى تتعلق بمزاولة المهنة ."}, {"number": "11", "chapter": "الفصل الأول", "text": "لمن رخص لها مزاولة مهنة التوليد التظلم من القرار الصادر بمجازاتها من مجلس التأديب المشار إلية فى المادة السابقة بشطب اسمها أو حرمانها من مزاولة المهنة . خلال خمسة عشر يوماً من تاريخ إخطارها بكتاب موصى عليه . ويفصل فى التظلم مجلس يصدر بتشكيلة قرار من وزير الصحة برئاسة أحد رؤساء الإدارات المركزية بوزارة الصحة أو من يقوم مقامة ومن اثنين من مديرى العموم بالوزارة أحدهما مدير عام الشئون القانونية ."}, {"number": "12", "chapter": "الفصل الأول", "text": "للمحافظ بناء على تقرير من الإدارة الصحية المختصة أن يشطب اسم المرخص لها بمزاولة المهنة من السجل إذا ثبت إنها أصبحت صحية لا تسمح لها بالاستمرار فى ممارسة مهنتها ."}, {"number": "13", "chapter": "الفصل الأول", "text": "دون إخلال بأى عقوبة أشد ينص عليها القانون ، يعاقب بالحبس مدة لا تزيد على ستة اشهر وبغرامة لا تقل عن مائتى جنية ولا تزيد على خمسمائة جنية أو بإحدى هاتين العقوبتين ، كل من زاول مهنة التوليد على وجه يخالف أحكام هذا القانون ، ويعاقب بالعقوبتين معا فى حالة العود ."}, {"number": "14", "chapter": "الفصل الثانى", "text": "يجب التبليغ عن المواليد خلال خمسة عشر يوماً من تاريخ حدوث الولادة ، ويكون التبليغ على النموذج المعد لذلك إلى مكتب الصحة فى الجهة التى حدثت فيها الولادة إذا وجد بها مكتب أو إلى الجهة الصحية فى الجهات التى ليست بها مكاتب صحة أو إلى العمدة فى غيرها من الجهات ، وذلك على النحو الذى تبينة اللائحة التنفيذية . وعلى العمدة إرسال التبليغات إلى مكتب الصحة أو إلى الجهة الصحية خلال سبعة أيام من تاريخ التبليغ بالولادة . وعلى مكتب الصحة أو الجهة الصحية إرسال التليغات إلى مكتب السجل المدنى المختص خلال ثلاثة أيام من تاريخ تبليغها لقيدها فى سجل المواليد."}, {"number": "15", "chapter": "الفصل الثانى", "text": "الأشخاص المكلفون بالتبليغ عن الولادة هم : 1 - والد الطفل إذا كان حاضرا . 2 - والدة الطفل شريطة إثبات العلاقة الزوجية على النحو الذى تبينه اللائحة التنفيذية . 3 - مديرو المستشفيات والمؤسسات العقابية ودور الحجر الصحى وغيرها من الأماكن التى تقع فيها الولادات . 4 - العمدة أو الشيخ . كما يجوز قبول التبليغ ممن حضر الولادة من الأقارب والأصهار البالغين حتى الدرجة الثانية على النحو الذى تبينه اللائحة التنفيذية . ويسأل عن عدم التبليغ فى المواعيد المقررة المكلفون بة بالترتيب السابق ، ولا يجوز قبول التبليغ من غير الأشخاص السابق ذكرهم . ويجب على الأطباء والمرخص لهن بالتوليد إعطاء شهادة بما يحررونه من ولادات تؤكد صحة الواقعة وتاريخها واسم أم المولود ونوعه ، كما يجب على أطباء الوحدات الصحية ومفتشى الصحة إصدار شهادات بنفس المضمون بعد توقيع الكشف الطبى إذا طلب منهم ذلك فى حالات التوليد الأخرى . مع عدم الإخلال بأحكام المواد (4 ، 21 ، 22) من هذا القانون ، للأم الحق فى الإبلاغ عن وليدها وقيده بسجلات المواليد ، واستخراج شهادة ميلاد له مدونا بها اسمها ، ولا يعتد بهذه الشهادة فى غير إثبات واقعة الميلاد . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "16", "chapter": "الفصل الثانى", "text": "يجب أن يشتمل التبليغ على البيانات الآتية : - يوم الولادة وتاريخها . - نوع الطفل ( ذكر أو أنثى ) واسمه ولقبة . - اسم الوالدين ولقبهما وجنسيتهما وديانتهما ومحل إقامتهما ومهنتهما - محل قيدهما إذا كان معلوما للمبلغ . - أى بيانات أخرى يضيفها وزير الداخلية بقرار منة بالاتفاق مع وزير الصحة ."}, {"number": "17", "chapter": "الفصل الثانى", "text": "على أمين السجل المدنى إصدار شهادة الميلاد على النموذج المعد لذلك عقب قيد الواقعة ، وتتضمن البيانات المنصوص عليها فى المادة (16) من هذا القانون، وتسلم شهادة ميلاد الطفل الأولى بغير رسوم ولا اشتراك تأمين إلى رب أسرة المولود بعد التحقق من شخصيته . وتحدد اللائحة التنفيذية لهذا القانون غيرة من الأشخاص الذين يمكن تسليمهم شهادة الميلاد ، ويعامل المستخرج من الشهادة لمرة واحدة فقط المعاملة المقررة بالمادة الثانية من قانون صندوق تأمين الأسرة الصادر بالقانون رقم 11 لسنة 2004 . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "18", "chapter": "الفصل الثانى", "text": "إذا توفى المولود قبل التبليغ عن ولادته فيجب التبليغ عن ولادته ثم وفاته ، أما إذا ولد ميتا بعد الشهر السادس من الحمل فيكون التبليغ مقصورا على وفاته ."}, {"number": "19", "chapter": "الفصل الثانى", "text": "إذا حدثت واقعة الميلاد أثناء السفر إلى الخارج وجب التبليغ عنها إلى أقرب قنصلية مصرية فى الجهة التى يقصدها المسافر أو إلى مكتب السجل المدنى المختص خلال ثلاثين يوما من تاريخ الوصول . وإذا حدثت واقعة الميلاد أثناء العودة فيكون التبليغ فى الأجل المذكور إلى مكتب الصحة أو الجهة الصحية الكائنة فى محل الإقامة ."}, {"number": "20", "chapter": "الفصل الثانى", "text": "على كل من عثر على طفل حديث الولادة فى المدن أن يسلمه فورا بالحالة التى عثر علية بها إلى إحدى المؤسسات المعدة لاستقبال الأطفال حديثى الولادة أو أقرب جهة شرطة التى عليها أن ترسله إلى إحدى المؤسسات ، وفى الحالة الأولى يجب على المؤسسة إخطار جهة الشرطة المختصة . وفى القرى يكون التسليم إلى العمدة أو الشيخ بمثابة التسليم إلى جهة الشرطة ، وفى هذه الحالة يقوم العمدة أو الشيخ بتسليم الطفل فورا إلى المؤسسة أو جهة الشرطة أيهما أقرب . وعلى جهة الشرطة فى جميع الأحوال أن تحرر محضرا يتضمن جميع البيانات الخاصة بالطفل ومن عثر علية ما لم يرفض الأخير ذلك ، ثم تخطر جهة الشرطة طبيب الجهة الصحية المختصة لتقدير سنة وتسميته تسمية ثلاثية ، وإثبات بياناته فى دفتر المواليد ، وترسل الجهة الصحية صورة المحضر وغيرة من الأوراق إلى مكتب السجل المدنى المختص خلال سبعة أيام من تاريخ القيد بدفتر مواليد الصحة . وعلى أمين السجل المدنى قيد الطفل فى سجل المواليد وإذا تقدم أحد الوالدين إلى جهة الشرطة بإقرار بأبوته أو أمومته للطفل حرر محضر بذلك تثبت فيه البيانات المنصوص عليها فى المادة (16) من هذا القانون ، وترسل صورة من المحضر إلى السجل المدنى المختص خلال سبعة أيام من تاريخ تحرير المحضر ."}, {"number": "21", "chapter": "الفصل الثانى", "text": "يكون قيد الطفل المشار إليه فى المادة السابقة طبقا للبيانات التى يدلى بها المبلغ وتحت مسئوليته عدا إثبات اسم الوالدين أو أحدهما فيكون بناء على طلب كتابى صريح ممن يرغب منهما . ولا يكون لهذا القيد حجية تتعارض مع القواعد المقررة فى شأن الأحوال الشخصية ."}, {"number": "22", "chapter": "الفصل الثانى", "text": "استثناء من حكم المادة السابقة لا يجوز لامين السجل ذكر اسم الوالد أو الوالدة أو كليهما معا ، وإن طلب منة ذلك ، فى الحالات الآتية : 1 - إذا كان الوالدان من المحارم فلا يذكر إسماهما . 2 - إذا كانت الوالدة متزوجة وكان المولود من غير زوجها فلا يذكر اسمها. 3 - بالنسبة إلى غير المسلمين ، إذا كان الوالد متزوجا وكان المولود من غير زوجته الشرعية فلا يذكر اسمه إلا إذا كانت الولادة قبل الزواج أو بعد فسخه ، وذلك عدا الأشخاص الذين يعتنقون دينا يجيز تعدد الزوجات . وتحدد اللائحة التنفيذية البيانات التى تذكر فى شهادة الميلاد فى الحالات سالفة الذكر ."}, {"number": "23", "chapter": "الفصل الثانى", "text": "يعاقب على مخالفة أحكام المواد ( 14 و 15 و 18 و 19 و 20 ) من هذا القانون بغرامة لا تقل عن عشرة جنيهات ولا تجاوز مائة جنية ."}, {"number": "24", "chapter": "الفصل الثانى", "text": "دون إخلال بأى عقوبة أشد ينص عليها القانون ، يعاقب بالحبس مدة لا تزيد على سنة وبغرامة لا تقل عن مائة جنية ولا تزيد على خمسمائة جنية أو بإحدى هاتين العقوبتين كل من أدلى عمدا ببيان غير صحيح من البيانات التى يوجب القانون ذكرها عند التبليغ عن المولود ."}, {"number": "25", "chapter": "الفصل الثالث", "text": "يجب تطعيم الطفل وتحصينه الطعوم الواقية من الأمراض المعدية ، وذلك دون مقابل ، بمكاتب الصحة والوحدات الصحية ، وفقا للنظم والمواعيد التى تبينها اللائحة التنفيذية . ويقع واجب تقديم الطفل أو التحصين على عاتق والدة أو الشخص الذى يكون الطفل فى حصانته . ويجوز تطعيم الطفل أو تحصينه بالطعوم الواقية بواسطة طبيب خاص مرخص له بمزاولة المهنة ، بشرط أن يقدم من يقع علية واجب تقديم الطفل للتطعيم أو التحصين شهادة تثبت ذلك إلى مكتب الصحة أو الوحدة الصحية قبل انتهاء الميعاد المحدد ."}, {"number": "26", "chapter": "الفصل الثالث", "text": "دون إخلال بأحكام قانون العقوبات ، يعاقب على مخالفة أحكام المادة السابقة بغرامة لا تقل عن عشرين جنيها ولا تزيد على مائتى جنية ."}, {"number": "27", "chapter": "الفصل الرابع", "text": "يكون لكل طفل بطاقة صحية ، تسجل بياناتها فى سجل خاص بمكتب الصحة المختص ، تسلم لوالدة أو المتولى تربيته بعد إثبات رقمها على شهادة الميلاد . وتحدد اللائحة التنفيذية كيفية تنظيم وبيانات هذه البطاقة ."}, {"number": "28", "chapter": "الفصل الرابع", "text": "تقدم البطاقة الصحية عند كل فحص طبى للطفل بالوحدات الصحية أو مراكز رعاية الأمومة والطفولة أو غيرها من الجهات الطبية المختصة . ويثبت بها الطبيب المختص الحالة الصحية للطفل ، كما يسجل بها تطعيم الطفل أو تحصينه وتاريخ إجراء التطعيم أو التحصين ."}, {"number": "29", "chapter": "الفصل الرابع", "text": "يجب تقديم البطاقة الصحية مع أوراق التحاق الطفل بمرحلتى التعليم قبل الجامعى ، وتحفظ البطاقة بالملف المدرسى للطفل ، ويسجل بها طبيب المدرسة نتيجة متابعة الحالة الصحية للطفل طوال مرحلتى الدراسة . ويجب على المدرسة أن تتحقق من وجود البطاقة الصحية بالنسبة إلى الأطفال الذين التحقوا قبل تاريخ العمل بهذا القانون ، فإذا لم توجد هذه البطاقة يتعين على والد الطفل أو المتولى تربيته إنشاء بطاقة وفقا لحكم المادة (27) من هذا القانون . وتحدد اللائحة التنفيذية كيفية تنظيم الفحص الدورى لصحة الطفل بالمدرسة خلال مرحلتى التعليم قبل الجامعى ، على أن يتم هذا الفحص مرة كل سنة على الأقل ."}, {"number": "30", "chapter": "الفصل الخامس", "text": "لا يجوز إضافة مواد ملونة أو حافظة أو أى إضافات غذائية إلى الأغذية والمستحضرات المخصصة لتغذية الرضع والأطفال إلا إذا كانت مطابقة للشروط والأحكام التى تبينها اللائحة التنفيذية . ويجب أن تكون أغذية الأطفال وأوعيتها خالية من المواد الضارة بالصحة ومن الجراثيم المرضية التى يحددها وزير الصحة . ويحظر تداول تلك الأغذية والمستحضرات أو الإعلان عنها بأى طريقة من طرق الإعلان ، إلا بعد تسجيلها والحصول على ترخيص بتداولها وبطريقة الإعلان عنها من وزارة الصحة ، وذلك وفقا للشروط والإجراءات التى يصدر بتحديدها قرار من وزير الصحة بالاتفاق مع وزير التموين . ومع عدم الإخلال بأى عقوبة أشد ينص عليها قانون آخر ، يعاقب كل من يخالف أيا من أحكام هذه المادة بالحبس لمدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسمائة جنية ولا تزيد عن ألفى جنية او بإحدى هاتين العقوبتين ، وفى جميع الأحوال يحكم بمصادرة المواد الغذائية والأوعية وأدوات الإعلان موضوع الجريمة ."}, {"number": "31", "chapter": "الفصل الأول", "text": "يعتبر دارا للحضانة كل مكان مناسب يخصص لرعاية الأطفال الذين لم يبلغوا سن الرابعة ، وتخضع دور الحضانة لإشراف ورقابة وزارة الشئون الاجتماعية طبقا لأحكام هذا القانون . ولكل طفل من المشار إليهم فى الفقرة الأولى الحق فى التمتع بخدمات دور الحضانة ، وتتخذ الدولة جميع التدابير اللازمة لكفالة هذا الحق . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "31 مكرر", "chapter": "الفصل الأول", "text": "ينشأ فى كل سجن للنساء دار للحضانة يتوافر فيها الشروط المقررة لدور الحضانة ، يسمح فيها بإيداع أطفال السجينات حتى بلوغ الطفل سن أربع سنوات ، على أن تلازم الأم طفلها خلال السنة الأولى من عمره . ويصدر بتنظيم كيفية اتصال الأم السجينة بطفلها وتلقيه رعايتها قرار من وزير الداخلية ، ولا يسمح للأم باصطحاب طفلها إلى محبسها ، ولا يجوز حرمانها من رؤية طفلها أو من رعايته كجزاء لمخالفة ترتكبها . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "32", "chapter": "الفصل الأول", "text": "تهدف دور الحضانة إلى تحقيق الأغراض الآتية : 1- رعاية الأطفال اجتماعيا وتنمية مواهبهم وقدراتهم . 2 - تهيئة الأطفال بدنيا وثقافيا ونفسيا وأخلاقيا تهيئة سليمة بما يتفق مع أهداف المجتمع وقيمة الدينية . 3 - نشر الوعى بين أسر الأطفال لتنشئتهم تنشئة سليمة . 4 - تقوية وتنمية الروابط الاجتماعية بين الدار وأسر الأطفال . 5 - تلبية حاجة الأطفال للترويح ومزاولة الألعاب والأنشطة الترفيهية والفنية المناسبة لأعمارهم . ويجب أن يتوافر لديها من الوسائل والأساليب ما يكفل تحقيق الأغراض السابقة وذلك طبقا لما تحدده اللائحة التنفيذية فى هذا الشأن . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "33", "chapter": "الفصل الأول", "text": "لا يجوز إنشاء دار للحضانة أو التغيير فى موقعها أو فى مواصفاتها قبل الحصول على ترخيص بذلك من السلطة المختصة . وفى حالة أيلولة الدار إلى غير المرخص له ، يجب على من آلت إلية أن يخطر مديرية الشئون الاجتماعية المختصة خلال تسعين يوما بموجب خطاب موصى علية مصحوب بعلم الوصول بهذه الأيلولة وسببها ، وعلية أن يرفق بالأخطار ما يفيد الشروط المقررة بالمادة (34) من هذا القانون ."}, {"number": "34", "chapter": "الفصل الأول", "text": "يتم الترخيص للأشخاص الطبيعيين أو الاعتبارية بإنشاء دور للحضانة وفقا للأحكام التى تحددها اللائحة التنفيذية ، ويشترط فيمن يرخص له من الأشخاص الطبيعيين أن يكون : 1 - مصرى الجنسية كامل الأهلية . 2 - لم يسبق الحكم علية فى جناية أو بعقوبة مقيدة للحرية فى جنحة مخلة بالشرف أو الأمانة أو فى جريمة من الجرائم المنصوص عليها فى المواد (283 و284 و 285 و 286 و 287 و 292و 293 ) من قانون العقوبات ، مالم يكن قد رد إلية اعتباره . 3 - حسن السيرة ذا سمعة اجتماعية طيبة . 4 - غير قائم بعمل أو بمهنة تتعارض مع العمل الاجتماعي أو التربوى ."}, {"number": "35", "chapter": "الفصل الأول", "text": "على من يرغب فى إنشاء دار للحضانة أن يقدم طلبا بذلك إلى مديرية الشئون الاجتماعية المختصة على النموذج المعد لذلك . وعلى مديرية الشئون البت فى الطلب فى ضوء احتياجات الجهة أو المنطقة أو الحى المزمع إقامة الدار به ، وذلك خلال ثلاثين يوماً من تاريخ تقديمه مع إخطار طالب الترخيص بقرارها بخطاب مصحوب بعلم الوصول ، فإذا كان قرارها بالرفض وجب أن يكون مسببا . ويجوز لمن رفض طلبة التظلم إلى اللجنة المشار إليها فى المادة (40) من هذا القانون ."}, {"number": "36", "chapter": "الفصل الأول", "text": "يلتزم الطالب فى حالة الموافقة على طلبة بإعداد جميع مستلزمات تشغيل الدار وإخطار مديرية الشئون الاجتماعية بمجرد انتهائه من ذلك بخطاب موصى علية بعلم الوصول ، وعلى المديرية خلال خمسة عشر يوما من تاريخ وصول الخطاب إليها التحقق من استيفاء الدار لجميع المواصفات والا طلبت منة استكمال النقص فيها ثم إخطارها ، وعليها خلال خمسة عشر يوما من تاريخ استلام هذا الإخطار إعادة المعاينة للتحقق من استكمال المطلوب وإصدار الترخيص متى ثبت لها ذلك ."}, {"number": "37", "chapter": "الفصل الأول", "text": "تتمتع دار الحضانة المرخص بها لشخص طبيعى بالشخصية الاعتبارية ، وتتمتع كذلك بهذه الشخصية إذا كان الترخيص بها لشخصية اعتبارية مالم يكن الترخيص ممنوحا لجمعية من أغراضها إنشاء دار للحضانة ويمثل دار الحضانة قانونا المرخص له بها أمام القضاء وفى مواجهة الغير . وعلى المرخص له بإنشاء دار الحضانة تعيين من يقوم بإدارتها طبقا للشروط التى تحددها اللائحة التنفيذية . ويلتزم المرخص له بوضع لائحة داخلية خلال ثلاثين يوماً من تاريخ صدور الترخيص للدار تعتمد من مديرية الشئون الاجتماعية المختصة ، وتحدد اللائحة التنفيذية القواعد والشروط التى يجب أن تتضمنها اللائحة النموذجية لدور الحضانة . وتمسك السجلات والدفاتر اللازمة لتنظيم العمل بدار الحضانة من النواحى الفنية والمالية والإدارية طبقا للنماذج التى تضعها وزارة الشئون الاجتماعية بها بمقر الدار ."}, {"number": "38", "chapter": "الفصل الأول", "text": "يجوز لدار الحضانة قبول الإعانات والهبات والتبرعات والوصايا المقدمة من الأفراد أو الهيئات المصرية ، أما تلك التى تقدم من افرد أو هيئات أجنبية أو دولية فلا يجوز قبولها إلا بموافقة وزارة الشئون الاجتماعية . وتخصص لإعانة دور الحضانة ، على النحو الذى تحدده اللائحة التنفيذية نسبة من الجزء المخصص من أرباح الشركات للخدمات الاجتماعية المركزية ، وتضاف هذه النسبة إلى موارد الصناديق الفرعية للمحافظات لإعانة الجمعيات والمؤسسات الخاصة بها . وتبين اللائحة التنفيذية طريقة وشروط توزيع الإعانات من حصيلة هذه النسبة فى المحافظات على دور الحضانة الموجودة بها ."}, {"number": "39", "chapter": "الفصل الأول", "text": "تتولى الأجهزة الفنية المختصة بوزارة الشئون الاجتماعية التفتيش الفنى والإشراف المالى والادارى على دور الحضانة للتحقق من تنفيذ أحكام هذا القانون والقرارات الصادرة تنفيذا له وتتولى مديرية الشئون الاجتماعية المختصة إخطار الدار بما يتبين لها من أوجه المخالفة مع أنذارها بتصحيحها خلال مهلة مناسبة تحدد لها ، فإذا لم تقم بتلافيها وتصحيحها رفعت الأمر إلى لجنة شئون دور الحضانة بالمحافظة لاتخاذ ما تراه ملائما فى هذا الشأن وفقا لأحكام المادة (40) من هذا القانون ."}, {"number": "40", "chapter": "الفصل الأول", "text": "تنشأ بكل محافظة لجنة تسمى لجنة شئون دور الحضانة برئاسة المحافظ أو من ينيبه ، وتحدد اللائحة التنفيذية كيفية تشكيلها ونظام عملها ، وتختص هذه اللجنة بالبت فيما يلى : 1- تظلمات أصحاب الشأن من قرارات المديرية برفض الترخيص بإنشاء الدار أو استكمال النقص الموجود بها أو تتغير مكانها أو نقل ملكيتها أو غلقها . 2 - غلق الدار مؤقتا أو وضعها تحت الإدارة المباشرة لمديرية الشئون الاجتماعية إذا ثبت لدى اللجنة أن إدارة الدار قد ساءت بحيث يتعذر عليها أداء رسالتها أو قيامها بالتزاماتها على الوجه الصحيح أو أن الدار تستغل فى غير أغراضها ، ويترتب على وضع الدار تحت إدارة المديرية غل يد القائم على إدارتها وتولى إدارتها نيابة عنة لحين إزالة أسباب المخالفة أو البت نهائيا فى وضع الدار . 3- اقتراح المديرية وقف صرف الإعانة المقررة للدار فى حالة مخالفتها أحكام القانون أو القرارات الصادرة تنفيذا له ، وتوجيه المبلغ الموقوف صرفة لإصلاح المخالفة . 4 - منح مهلة إضافية للدار لحين إزالة أسباب المخالفة ، فإذا لم تقم بذلك كان للجنة أن تضعها تحت الإدارة المباشرة لمديرية الشئون الاجتماعية وفقاً لأحكام البند (2) . وتفصل اللجنة فيما يعرض عليها خلال ثلاثين يوما على الأكثر وإلا اعتبر انقضاء هذه المدة دون البت قرارا بالرفض ."}, {"number": "41", "chapter": "الفصل الأول", "text": "لا يجوز إغلاق الدار بعد الترخيص بها إلا بقرار مسبب يصدر من لجنة شئون دور الحضانة بالمحافظة. ومع ذلك يجوز لمدير مديرية الشئون الاجتماعية بالمحافظة فى حالة الضرورة القصوى إغلاق الدار مؤقتا بقرار مسبب يكون نافذا فور صدوره ، على أن يتم عرضة على لجنة شئون دور الحضانة بالمحافظة خلال ثلاثين يوما لاتخاذ ما تراه طبقا لأحكام المادة السابقة. ويترتب على عدم مراعاة الميعاد المشار إلية اعتبار القرار كأن لم يكن ."}, {"number": "42", "chapter": "الفصل الأول", "text": "تعتبر أموال دور الحضانة أموالا عامة ويعتبر العاملون بها موظفين عموميين فى تطبيق أحكام الباب الرابع من الكتاب الثانى من قانون العقوبات كما تعتبر السجلات والدفاتر التى تمسكها أوراقا رسمية فى تطبيق أحكام التزوير الواردة فى قانون العقوبات ."}, {"number": "43", "chapter": "الفصل الأول", "text": "تنشأ بقرار من الوزير المختص بالشئون الاجتماعية لجنة عليا لدور الحضانة تشكل برئاسته وعضوية عدد من ممثلى الوزارات المعنية ومن المهتمين بشئون الطفولة والأمومة يصدر بتعيينهم قرار منة بعد موافقة الجهات التى يتبعونها وتختص اللجنة المذكورة برسم السياسة العامة لدور الحضانة ومتابعة تنفيذها . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "44", "chapter": "الفصل الأول", "text": "يعاقب بالحبس وبغرامة لا تقل عن خمسمائة جنية ولا تجاوز خمسة آلاف جنية أو بإحدى هاتين العقوبتين كل من أنشا أو أدارا للحضانة أو غير فى موقعها أو مواصفاتها قبل الحصول على ترخيص من السلطة المختصة ، وتكون العقوبة الحبس مدة لا تقل عن سنة إذا لم تتوافر فيه احد الشروط المقررة بالبنود 1، 2، 3 من المادة (34) من هذا القانون . ويجوز للنيابة العامة بناء على طلب مديرية الشئون الاجتماعية أن تأمر بغلق الدار المنشأة بغير ترخيص مؤقتا لحين الفصل فى الدعوى ، ولصاحب الدار أن يتظلم من هذا الأمر إلى القاضى الجزئى المختص خلال أسبوع من إخطاره به."}, {"number": "45", "chapter": "الفصل الأول", "text": "يعاقب بالحبس مدة لا تجاوز سنة وبغرامة لا تقل عن مائتى جنية ولا تجاوز ألفى جنية أو بإحدى هاتين العقوبتين كل من خالف أحكام الفقرة الثانية من المادة (33) والمادة (37) من هذا القانون."}, {"number": "46", "chapter": "الفصل الثانى", "text": "يهدف نظام الأسر البديلة إلى توفير الرعاية الاجتماعية والنفسية والصحية والمهنية للأطفال الذين جاوزت سنهم ثلاثة أشهر والذين حالت ظروفهم دون أن ينشأوا فى أسرهم الطبيعية ، وذلك بهدف تربيتهم تربية سليمة وتعويضهم هما فقدوة من عطف وحنان. وتحدد اللائحة التنفيذية القواعد والشروط لمنظمة لمشروع الأسر البديلة والفئات المنتفعة به ."}, {"number": "معدلة بالقانون رقم", "chapter": "الفصل الثانى", "text": "6 لسنة 2015"}, {"number": "47", "chapter": "الفصل الثانى", "text": "يعتبر نادى الطفل مؤسسة اجتماعية وتربوية تكفل توفير الرعاية الاجتماعية للأطفال من سن السادسة إلى الرابعة عشرة ، عن طريق شغل أوقات فراغهم بالوسائل والأساليب التربوية السليمة - بهدف النادى إلى تحقيق الأغراض الآتية : 1 - رعاية الأطفال اجتماعيا وتربويا خلال أوقات فراغهم أثناء فترة الأجازات وقبل بدء اليوم الدراسى وبعدة . 2 - استكمال رسالة الأسرة والمدرسة حيال الطفل والعمل على مساعدة أم الطفل العاملة لحماية الأطفال من الإهمال البدنى والروحى ووقايتهم من التعرض للانحراف . 3 - تهيئة الفرصة للطفل لكى ينمو نموا متكاملا من جميع النواحى البدنية والعقلية والوجدانية لاكتساب خبرات ومهارات جديدة والوصول إلى أكبر قدر ممكن من تنمية قدراته الكامنة . 4 - معاونة الأطفال على زيادة تحصيلهم الدراسى . 5 - تقوية الروابط بين النادى وأسر الأطفال . 6- تهيئة أسر الطفل ومدها بالمعرفة ونشر التوعية حول تربية الطفل وعوامل تنشئته وإعداده وفق الأساليب التربوية الصحيحة . وتبين اللائحة التنفيذية كيفية إصدار اللائحة النموذجية لنوادى الطفل ."}, {"number": "48", "chapter": "الفصل الثانى", "text": "يقصد بمؤسسة الرعاية الاجتماعية للأطفال المحرومين من الرعاية الأسرية كل دار لإيواء الأطفال الذين لا تقل سنهم عن ست سنوات ولا تزيد على ثمانى عشرة سنة ، المحرومين من الرعاية الأسرية بسبب اليتم أو تصدع الأسرة أو عجزها عن توفير الرعاية الأسرية السليمة للطفل. ويجوز استمرار الطفل فى المؤسسة إذا كان ملتحقا بالتعليم العالى إلى أن يتم تخرجه متى كانت الظروف التى أدت إلى التحاقه بالمؤسسة قائمة واجتاز مراحل التعليم بنجاح . وتبين اللائحة التنفيذية كيفية إصدار اللائحة النموذجية لتلك المؤسسات ."}, {"number": "49", "chapter": "الفصل الثانى", "text": "يكون للأطفال الآتى بيانهم الحق فى الحصول على معاش شهرى من الوزارة المختصة بالضمان الاجتماعى لا يقل عن ستين جنيها ووفقا للشروط والقواعد المبينة فى قانون الضمان الاجتماعى : 1- الأطفال الأيتام ، أو مجهولو الأب أو الأبوين . 2- أطفال الأم المعيلة ، وأطفال الأم المطلقة إذا تزوجت أو توفيت . 3- أطفال المحتجز قانونا ، أو المسجون ، أو المسجونة المعيلة ، والمحبوس ، أو المحبوسة المعيلة ، لمدة لا تقل عن شهر . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "50", "chapter": "الفصل الثالث", "text": "لا يجوز منح الطفل ترخيصا بقيادة أى مركبة آلية . ومع عدم الإخلال بحكم المادة (101) من هذا القانون ، يعاقب بالحبس مدة لا تزيد على ثلاثة أشهر وبغرامة لا تقل عن خمسين جنيها ولا يزيد على مائة جنية أو بإحدى هاتين العقوبتين كل طفل قاد مركبة آلية بغير ترخيص . ومع عدم الإخلال بأحكام قانون المرور يعاقب بذات العقوبة كل من أجر للطفل أو مكنة على أى نحو من قيادة مركبة آلية ، ويجوز للمحكمة إيقاف رخصة المركبة لمدة لا تزيد على ثلاثة أشهر ، وإيقاف رخصة المكان المخصص للتأجير لنفس المدة ، وفى حالة العود يجب الحكم بإلغاء رخصة المكان أو غلقه إن لم يكن مرخصا به . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "51", "chapter": "الفصل الثالث", "text": "لا يجوز قيادة دراجات الركوب فى الطريق العام لمن تقل سنه عن ثمانى سنوات ميلادية ويكون متولى أمر الطفل مسئولا عما ينجم عن ذلك من إضرار ."}, {"number": "52", "chapter": "الفصل الثالث", "text": "لا يجوز لمؤجرى دراجات الركوب وعمالهم تأجيرها لمن تقل سنه عن ثمانى سنوات ، وإلا كانوا مسئولين عما ينجم عن ذلك من أضرار للغير وللطفل نفسه."}, {"number": "53", "chapter": "الفصل الأول", "text": "يهدف تعليم الطفل بمختلف مراحل التعليم إلى تحقيق الغايات التالية : 1- تنمية شخصية الطفل ومواهبه وقدراته العقلية والبدنية إلى أقصى إمكاناتها ، مع مراعاة اتفاق برامج التعليم مع كرامة الطفل وتعزيز شعوره بقيمته الشخصية وتهيئته للمشاركة وتحمل المسئولية . 2- تنمية احترام الحقوق والحريات العامة للإنسان . 3- تنمية احترام الطفل لذويه ولهويته الثقافية ولغته وللقيم الدينية والوطنية . 4- تنشئة الطفل على الانتماء لوطنه والوفاء له ، وعلى الإخاء والتسامح بين البشر ، وعلى احترام الآخر . 5- ترسيخ قيم المساواة بين الأفراد وعدم التمييز بسبب الدين أو الجنس أو العرق أو العنصر أو الأصل الاجتماعى أو الإعاقة أو أى وجه آخر من وجوه التمييز . 6- تنمية احترام البيئة الطبيعية والمحافظة عليها . 7- إعداد الطفل لحياة مسئولة فى مجتمع مدنى متضامن قائم على التلازم بين الوعى بالحقوق والالتزام بالواجبات . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "54", "chapter": "الفصل الأول", "text": "التعليم حق لجميع الأطفال فى مدارس الدولة بالمجان . وتكون الولاية التعليمية على الطفل للحاضن ، وعند الخلاف على ما يحقق مصلحة الطفل الفضلى يرفع أى من ذوى الشأن الأمر إلى رئيس محكمة الأسرة ، بصفته قضايا للأمور الوقتية ، ليصدر قراره بأمر على عريضة ، مراعيا مدى يسار ولى الأمر ، وذلك دون المساس بحق الحاضن فى الولاية التعليمية . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "55", "chapter": "الفصل الثانى", "text": "رياض الأطفال نظام تربوى يحقق التنمية الشاملة لأطفال ما قبل حلقة التعليم الابتدائى ويهيئهم للالتحاق بها ."}, {"number": "56", "chapter": "الفصل الثانى", "text": "مع عدم الإخلال بالأحكام الخاصة بدور الحضانة المنصوص عليها فى الباب الثالث ، تعتبر روضة أطفال كل مؤسسة تربوية للأطفال قائمة بذاتها وكل فصل أو فصول ملحقة بمدرسة رسمية وكل دار تقبل الأطفال بعد سن الرابعة ، وتقوم على الأهداف المنصوص عليها فى المادة التالية ."}, {"number": "57", "chapter": "الفصل الثانى", "text": "تهدف رياض الأطفال إلى مساعدة أطفال ما قبل سن المدرسة على تحقيق التنمية الشاملة والمتكاملة لكل طفل فى المجالات العقلية والبدنية والحركية والوجدانية والاجتماعية والخلقية والدينية ."}, {"number": "58", "chapter": "الفصل الثانى", "text": "تخضع رياض الأطفال لخطط وبرامج وزارة التعليم ولإشرافها الادارى والفنى ، وتحدد اللائحة التنفيذية مواصفاتها وكيفية إنشائها وتنظيم العمل فيها وشروط القبول ومقابل الالتحاق بها ."}, {"number": "59", "chapter": "الفصل الثالث", "text": "تكون مرحلتا التعليم قبل الجامعى على النحو التالى : 1- مرحلة التعليم الاساسى الالزامى ، وتتكون من حلقتين ، الحلقة الابتدائية ، والحلقة الإعدادية ، ويجوز إضافة حلقة أخرى ، وذلك على النحو الذى تبينه اللائحة التنفيذية . 2 - مرحلة التعليم الثانوى ( العام والفنى ) ."}, {"number": "60", "chapter": "الفصل الثالث", "text": "يهدف التعليم الاساسى إلى تنمية قدرات واستعدادات التلاميذ وإشباع ميولهم وتزويدهم بالقدر الضرورى من القيم والسلوكيات والمعارف والمهارات العملية والمهنية التى تتفق وظروف بيئاتهم المختلفة ، بحيث يمكن لمن يتم مرحلة التعليم الاساسى أن يواصل تعليمة فى مرحلة أعلى وان يواجه الحياة بعد تدريب مهنى مناسب ، وذلك من أجل إعداد الفرد لكى يكون مواطنا منتجا فى بيئته ومجتمعة ."}, {"number": "61", "chapter": "الفصل الثالث", "text": "تهدف مرحلة التعليم الثانوى العام إلى إعداد الطلاب للحياة العملية وإعدادهم للتعليم العالى والجامعى والمشاركة فى الحياة العامة ، والتأكيد على ترسيخ القيم الدينية والسلوكية والقومية."}, {"number": "62", "chapter": "الفصل الثالث", "text": "يهدف التعليم الثانوى الفنى أساسا إلى إعداد فئة من الفنيين فى مجالات الصناعة والزراعة والإدارة والخدمات ، وتنمية الملكات الفنية لدى الدارسين."}, {"number": "63", "chapter": "الفصل الثالث", "text": "تسرى أحكام قانون التعليم فيما لم يرد بشأنه نص فى هذا الباب ."}, {"number": "64", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بنص الفقرة الثانية من المادة (18) من قانون التعليم الصادر بالقانون رقم 139 لسنة 1981 ، يحظر تشغيل الأطفال قبل بلوغهم خمس عشرة سنة ميلادية كاملة ، كما يحظر تدريبهم قبل بلوغهم ثلاث عشرة سنة ميلادية . ويجوز بقرار من المحافظ المختص ، بعد موافقة وزير التعليم ، الترخيص بتشغيل الأطفال من سن ثلاث عشرة إلى خمس عشرة سنة فى أعمال موسمية لا تضر بصحتهم أو نموهم ولا تخل بمواظبتهم على الدراسة . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "65", "chapter": "الفصل الأول", "text": "يحظر تشغيل الطفل فى أى من أنواع الأعمال التى يمكن ، بحكم طبيعتها أو ظروف القيام بها ، أن تعرض صحة أو سلامة أو أخلاق الطفل للخطر ، ويحظر بشكل خاص تشغيل أى طفل فى أسوأ أشكال عمل الأطفال المعرفة فى الاتفاقية رقم 182 لسنة 1999 . ومع مراعاة ما هو منصوص علية فى الفقرة الأولى تبين اللائحة التنفيذية لهذا القانون نظام تشغيل الأطفال والأحوال التى يجوز فيها التشغيل والأعمال والحرف والصناعات التى يعملون بها وفقا لمراحل السن المختلفة . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "65 مكرر", "chapter": "الفصل الأول", "text": "يجرى الفحص الطبى قبل إلحاقه بالعمل للتأكد من أهليته الصحية للعمل الذى يلحق به، ويعاد الفحص دوريا مرة ، على الأقل ، كل سنة ، وذلك على النحو الذى تبينه اللائحة التنفيذية . وفى جميع الأحوال يجب ألا يسبب العمل آلاما أو أضرارا بدنية أو نفسية للطفل ، أو يحرمه من فرصته فى الانتظام فى التعليم والترويح وتنمية قدراته ومواهبه ، ويلزم صاحب العمل بالتأمين علية وحمايته من أضرار المهنة خلال فترة عملة . وتزاد إجازة الطفل العامل السنوية عن إجازة العامل البالغ سبعة أيام ، ولا يجوز تأجيلها أو حرمانه منها لأى سبب . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "66", "chapter": "الفصل الأول", "text": "ولا يجوز تشغيل الطفل أكثر من ست ساعات فى اليوم ، ويجب أن تتخلل ساعات العمل فترة أو أكثر لتناول الطعام والراحة لا تقل فى مجموعها عن ساعة واحدة ، وتحدد هذه الفترة أو الفترات بحيث لا يشتعل الطفل أكثر من أربع ساعات متصلة . ويحظر تشغيل الأطفال ساعات عمل إضافية أو تشغيلهم فى أيام الراحة الأسبوعية أو العطلات الرسمية . وفى جميع الأحوال لا يجوز تشغيل الأطفال فيما بين الساعة السابعة مساء والسابعة صباحاً . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "67", "chapter": "الفصل الأول", "text": "يلتزم كل صاحب عمل يستخدم طفلا دون السادسة عشرة بمنحه بطاقة تثبت أنه يعمل لديه، وتلصق عليها صورة الطفل ، وتعتمد من مكتب القوى العاملة وتختم بخاتمه ."}, {"number": "68", "chapter": "الفصل الأول", "text": "على صاحب العمل الذى يقوم بتشغيل طفل أو أكثر مراعاة الآتى : 1- أن يعلق فى مكان ظاهر من محل العمل نسخة تحتوى على الأحكام التى يتضمنها هذا الفصل . 2- أن يحرر أولا بأول كشفا بالبيانات الأساسية المتعلقة بكل طفل من المشتغلين لديه، يشتمل على اسمه وتاريخ ميلاده وطبيعة نشاطه وعدد ساعات عملة وفترات راحته ومضمون الشهادة المثبتة لأهليته للعمل ويقدم الكشف للمختصين عند طلبه . 3- أن يبلغ الجهة الإدارية المختصة بأسماء الأطفال الجارى تشغيلهم وأسماء الأشخاص المنوط بهم مراقبة أعمالهم . 4- أن يقوم بتوفير سكن منفصل للعمال من الأطفال عن غيرهم من البالغين ، إذا اقتضت ظروف العمل مبيتهم . 5- أن يحتفظ بمقر العمل بالوثائق الرسمية التى تثبت سن جميع العاملين لدية من الأطفال ومقدرتهم الصحية ، ويقدمها عند الطلب ، ويعتبر صاحب العمل مسئولا عن التأكد من سن الأطفال العاملين لديه . 6- أن يوفر بمقر العمل جميع احتياطيات الصحة والسلامة المهنية ويدرب الأطفال العاملين على استخدامها . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "69", "chapter": "الفصل الأول", "text": "على صاحب العمل أن يسلم الطفل نفسه أو أحد والدية أجرة أو مكافآته وغير ذلك مما يستحقه ، ويكون هذا التسليم مبرئا لذمته ."}, {"number": "70", "chapter": "الفصل الثانى", "text": "للعاملة فى الدولة والقطاع العام وقطاع الأعمال العام والقطاع الخاص ، سواء كانت تعمل بصفة دائمة أو بطريق التعاقد المؤقت ، الحق فى إجازة وضع مدتها ثلاثة أشهر بعد الوضع بأجر كامل ، وفى جميع الأحوال لا تستحق العاملة هذه الإجازة لأكثر من ثلاثة مرات طوال مدة خدمتها . وتخفض ساعات العمل اليومية للمرأة الحامل ساعة على الأقل اعتبارا من الشهر السادس للحمل ، ولا يجوز تشغيلها ساعات عمل إضافية طوال مدة الحمل وحتى نهاية ستة أشهر من تاريخ الولادة . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "71", "chapter": "الفصل الثانى", "text": "يكون للعاملة التى ترضع طفلها خلال السنتين التاليتين لتاريخ الوضع - فضلا عن مدة الراحة المقررة - الحق فى فترتين أخريين لهذا الغرض لا تقل كل منهما نصف ساعة ، وللعاملة الحق فى ضم هاتين الفترتين ، وتحسب هاتان الفترتان من ساعات العمل ولا يترتب على ذلك أى تخفيض فى الأجر."}, {"number": "72", "chapter": "الفصل الثانى", "text": "للعاملة فى الدولة والقطاع العام الأعمال العام الحصول على أجازة بدون اجر لمدة سنتين لرعاية طفلها ، وتستحق ثلاث مرات طوال مدة خدمتها . واستثناء من أحكام قانون التأمين الاجتماعى تتحمل الجهة التابعة لها العاملة باشتراكات التأمين المستحق عليها وعلى العاملة وفق أحكام هذا القانون ، أو أن تمنح العاملة تعويضا عن أجرها يساوى (25%) من المرتب الذى تستحقه فى تاريخ بدء فترة الأجازة وذلك وفقا لاختيارها. وفى القطاع الخاص يكون للعاملة فى المنشأة التى تستخدم خمسين عاملا فأكثر الحق فى الحصول على إجازة بدون اجر لمدة لا تجاوز سنتين ، وذلك لرعاية طفلها، ولا تستحق هذه الأجازة لأكثر من ثلاث مرات طوال مدة خدمتها ."}, {"number": "73", "chapter": "الفصل الثانى", "text": "على صاحب العمل الذى يستخدم مائة عاملة فأكثر فى مكان واحد أن ينشىء دارا للحضانة أو يعهد إلى دار للحضانة برعاية أطفال العاملات بالشروط والأوضاع التى تحددها اللائحة التنفيذية . وتلتزم المنشآت التى تقع فى منطقة واحدة وتستخدم كل منها أقل من مائة عاملة أن تشترك فى تنفيذ الالتزام المنصوص علية فى الفقرة السابقة بالشروط والأوضاع التى تحددها اللائحة التنفيذية ."}, {"number": "74", "chapter": "الفصل الثانى", "text": "يعاقب كل من يخالف أحكام الباب الخامس من هذا القانون بغرامة لا تقل عن مائة جنية ولا تزيد على خمسمائة جنية . وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم المخالفة ، وفى حالة العود تزاد العقوبة بمقدار المثل ، ولا يجوز وقف تنفيذها ."}, {"number": "75", "chapter": "الباب السادس", "text": "تكفل الدولة وقاية الطفل من الإعاقة ومن كل عمل من شأنه الإضرار بصحته أو بنموه البدنى أو العقلى أو الروحى أو الاجتماعى ، وتعمل على اتخاذ التدابير اللازمة للكشف المبكر على الإعاقة ، وتأهيل وتشغيل المعاقين عند بلوغ سن العمل . وتتخذ التدابير اللازمة المناسبة لإسهام وسائل الإعلام فى برامج التوعية والإرشاد فى مجال الوقاية من الإعاقة ، والتبصير بحقوق الأطفال المعاقين ، وتوعيتهم والقائمين على رعايتهم بما ييسر إدماجهم فى المجتمع . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "76", "chapter": "الباب السادس", "text": "للطفل المعاق الحق فى التمتع برعاية خاصة ، اجتماعية وصحية ونفسية وتنمى اعتماده على نفسه وتيسر اندماجه ومشاركته فى المجتمع ."}, {"number": "76 مكرر", "chapter": "الباب السادس", "text": "للطفل المعاق الحق فى التربية والتعليم وفى التدريب والتأهيل المهنى فى ذات المدارس والمعاهد ومراكز التدريب المتاحة للأطفال غير المعاقين ، وذلك فيما عدا الحالات الاستثنائية الناتجة عن طبيعة ونسبة الإعاقة . وفى هذه الحالات الاستثنائية تلتزم الدولة بتأمين التعليم والتدريب فى فصول أو مدارس أو مؤسسات أو مراكز تدريب خاصة ، بحسب الأحوال ، تتوافر فيها الشروط التالية : 1- أن تكون مرتبطة بنظام التعليم النظامى وبنظام التدريب والتأهيل المهنى لغير المعاقين . 2- أن تكون ملائمة لاحتياجات الطفل المعاق وقريبة من مكان إقامته . 3- أن توفر تعليما أو تأهيلا كاملا بالنسبة لكل الأطفال المعاقين مهما كانت سنهم ودرجة إعاقتهم . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "77", "chapter": "الباب السادس", "text": "للطفل المعاق الحق فى التأهيل ، ويقصد بالتأهيل تقديم الخدمات الاجتماعية والنفسية والطبية والتعليمية والمهنية التى يلزم توفيرها للطفل المعاق وأسرته لتمكينه من التغلب على الآثار الناشئة عن عجزه . وتؤدى الدولة خدمات التأهيل والأجهزة التعويضية دون مقابل ، فى حدود المبالغ المدرجة لهذا الغرض فى الموازنة العامة للدولة مع مراعاة حكم المادة (85) من هذا القانون ."}, {"number": "78", "chapter": "الباب السادس", "text": "تنشىء وزارة الشئون الاجتماعية المعاهد والمنشآت اللازمة لتوفير خدمات التأهيل الأطفال المعاقين . ويجوز لها الترخيص فى إنشاء هذه المعاهد وفقا للشروط والأوضاع التى تحددها اللائحة التنفيذية . ولوزارة التعليم أن تنشىء مدارس أو فصولا لتعليم المعاقين من الأطفال بما يتلائم وقدراتهم واستعداداتهم، وتحدد اللائحة التنفيذية شروط القبول ومناهج الدراسة ونظم الامتحانات فيها ."}, {"number": "79", "chapter": "الباب السادس", "text": "تسلم الجهات المشار إليها فى الفقرتين الأولى والثانية من المادة السابقة دون مقابل أو رسوم شهادة لكل طفل معاق تم تأهيله، ويبين بالشهادة المهنة التى تم تأهيله لها ، بالإضافة إلى البيانات الأخرى وذلك على النحو الذى تبينه اللائحة التنفيذية ."}, {"number": "80", "chapter": "الباب السادس", "text": "تقوم جهات التأهيل بإخطار مكتب القوى العاملة الذى يقع فى دائرته محل إقامة الطفل المعاق بما يفيد تأهيله ، وتقيد مكاتب القوى العاملة أسماء الأطفال الذين تم تأهيلهم فى سجل خاص ، وتسلم الطفل المعاق أو من ينوب عنة شهادة بحصول القيد دون مقابل أو رسوم . وتلتزم مكاتب القوى العاملة بمعاونة المعاقين المقيدين لديها فى الالتحاق بالأعمال التى تناسب أعمارهم وكفايتهم ومحال إقامتهم ، وعليها إخطار مديرية الشئون الاجتماعية الواقعة فى دائرتها ببيان شهرى عن الأطفال المعاقين الذين تم تشغيلهم ."}, {"number": "81", "chapter": "الباب السادس", "text": "يصدر وزير القوى العاملة بالاتفاق مع الوزير المختص بالشئون الاجتماعية قرارا بتحديد أعمال معينة بالجهاز الادارى للدولة والهيئات العامة ووحدات القطاع العام وقطاع الأعمال العام تخصص للمعاقين من الأطفال الحاصلين على شهادة التأهيل ، وذلك وفقا للقواعد المنظمة لذلك قانونا . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "82", "chapter": "الباب السادس", "text": "على صاحب العمل الذى يستخدم خمسين عاملا فأكثر - سواء كانوا يعملون فى مكان أو أمكنة متفرقة فى مدينة أو قرية واحدة - استخدام الأطفال المعاقين الذين ترشحهم مكاتب القوى العاملة بحد أدنى اثنين فى المائة من بين نسبة الخمسة فى المائة المنصوص عليها فى القانون (39) لسنة 1975 بشأن تأهيل المعاقين . ويجوز لصاحب العمل شغل هذه النسبة باستخدام أطفال معاقين بغير طريق الترشيح من مكاتب القوى العاملة ، ممن سبق قيدهم بهذه المكاتب . ويخطر صاحب العمل مكتب القوى العاملة المختص بمن تم استخدامهم بكتاب موصى علية بعلم الوصول خلال عشرة أيام من تاريخ تسليمهم العمل ."}, {"number": "83", "chapter": "الباب السادس", "text": "على صاحب العمل - المشار اليه فى المادة السابقة - إمساك سجل خاص لقيد أسماء المعاقين الحاصلين على شهادات التأهيل الذين الحقوا بالعمل لدية يشتمل على البيانات الواردة فى شهادات التأهيل ويجب تقديم هذا السجل إلى مفتشى مكتب القوى العاملة الذى يقع فى دائراته نشاطه كلما طلبوا منة ذلك ، كما يجب إخطار هذا المكتب ببيان يتضمن عدد العاملين الاجمالى وعدد الوظائف التى يشغلها المعاقون المشار إليهم والأجر الذى يتقاضاه كل منهم ، وذلك فى الميعاد وطبقا للنموذج الذى تحدده اللائحة التنفيذية ."}, {"number": "84", "chapter": "الباب السادس", "text": "يعاقب كل من يخالف أحكام المادتين السابقتين بغرامة لا تقل عن مائة جنية ولا تجاوز ألف جنية . ويجوز الحكم بإلزام صاحب العمل بأن يدفع شهرياً للمعاق والمؤهل الذى امتنع عن استخدامه مبلغا يساوى الأجر المقرر أو التقديرى للعمل الذى رشح له وذلك اعتباراً من تاريخ إثبات المخالفة ولمدة لا تجاوز سنة ، ويزول هذا الالتزام إذا التحق الأخير بعمل مناسب ."}, {"number": "85", "chapter": "الباب السادس", "text": "ينشأ صندوق لرعاية الأطفال المعاقين وتأهيلهم ، تكون له الشخصية الاعتبارية ، ويصدر بتنظيمه وتحديد اختصاصاته قرار من رئيس الجمهورية ، ويدخل ضمن موارده الغرامات المقضى بها الجرائم المنصوص عليها فى هذا الباب ."}, {"number": "86", "chapter": "الباب السادس", "text": "تعفى من جميع أنواع الضرائب والرسوم الأجهزة التعويضية والمساعدة وقطع غيارها ، ووسائل وأجهزة إنتاجها ووسائل النقل اللازمة لاستخدام الطفل المعاق وتأهيله . ويحظر استعمال هذه الأجهزة والوسائل لغير المعاقين ، دون مقتضى ، ويعاقب على مخالفة ذلك بالحبس مدة لا تقل عن سنة وغرامة لا تقل عن ألفى جنية ولا تجاوز عشرة آلاف جنية والمصادرة . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "87", "chapter": "الباب السابع", "text": "تكفل الدولة إشباع حاجات الطفل الثقافية فى شتى مجالاتها من أدب وفنون ومعرفة وربطها بقيم المجتمع فى إطار التراث الانسانى والتقدم العلمى الحديث ."}, {"number": "88", "chapter": "الباب السابع", "text": "يتم إنشاء مكتبات للطفل فى كل قرية وفى الأحياء والأماكن العامة ، كما تنشأ تباعا نوادى ثقافة الطفل ويلحق بكل منها مكتبة ودار للسينما والمسرح ، وتحدد اللائحة التنفيذية كيفية إنشاء هذا المكتبات أو النوادى وتنظيم العمل بها ."}, {"number": "89", "chapter": "الباب السابع", "text": "يحظر نشر أو عرض أو تداول أى مطبوعات أو مصنفات فنية مرئية أو مسموعة خاصة بالطفل تخاطب غرائزه الدنيا ، أو تزين له السلوكيات المخالفة لقيم المجتمع أو يكون من شأنها تشجيعه على الانحراف . ومع عدم الإخلال بأى عقوبة أشد ينص عليها قانون آخر ، يعاقب على مخالفة حكم الفقرة السابقة بغرامة لا تقل عن مائة جنية ولا تزيد على خمسمائة جنية ، ويجب مصادرة المطبوعات أو المصنفات الفنية المخالفة ."}, {"number": "90", "chapter": "الباب السابع", "text": "يكون حظر ما يعرض على الأطفال فى دور السينما والأماكن العامة المماثلة طبقا للشروط والأوضاع التى تحددها اللائحة التنفيذية ، ويحظر على مديرى دور السينما وغيرها من الأماكن العامة المماثلة والتى يصدر بتحديدها قرار من وزير الثقافة ، وعلى مستغليها وعلى المشرفين على إقامة الحفلات والمسئولين عن إدخال الجمهور ، السماح للأطفال بدخول هذه الدور أو مشاهدة ما يعرض فيها إذا كان العرض محظورا عليهم طبقا لما تقرره جهة الاختصاص ، كما يحظر اصطحاب الأطفال عند الدخول لمشاهدة هذه الحفلات ."}, {"number": "91", "chapter": "الباب السابع", "text": "على مديرى دور السينما وغيرها من الأماكن العامة المماثلة أن يعلنوا فى مكان العرض وفى كافة وسائل الدعاية الخاصة ما يفيد حظر مشاهدة العرض على الأطفال ويكون ذلك الإعلان بطريقة واضحة ، وباللغة العربية ."}, {"number": "92", "chapter": "الباب السابع", "text": "مع عدم الإخلال بأى عقوبة أشد ينص عليها قانون آخر ، يعاقب على مخالفة أحكام المادة (90 ) من هذا القانون بغرامة لا تقل عن خمسين جنيها ، ولا تزيد على مائة جنية عن كل طفل . كما يعاقب على مخالفة أحكام المادة (91) من هذا القانون بغرامة لا تقل عن خمسين جنيها ولا تزيد على خمسمائة جنية ."}, {"number": "93", "chapter": "الباب السابع", "text": "يكون للموظفين الذين يصدر بتحديدهم قرار من وزير العدل بالاتفاق مع وزير الثقافة صفة الضبطية القضائية فى إثبات ما يقع بالمخالفة لأحكام هذا الباب والقرارات الصادرة بتنفيذه."}, {"number": "94", "chapter": "الباب الثامن", "text": "تمتنع المسئولية الجنائية على الطفل الذى لم يجاوز اثنتى عشرة سنة ميلادية كاملة وقت ارتكاب الجريمة . ومع ذلك إذا كان الطفل قد جاوزت سنة السابعة ولم تجاوز الثانية عشرة سنة ميلادية كاملة وصدرت منة واقعة تشكل جناية أو جنحة ، تتولى محكمة الطفل ، دون غيرها ، الاختصاص بالنظر فى أمرة ، ويكون لها أن تحكم بأحد التدابير المنصوص عليها فى البنود 1 ، 2 ، 7 ، 8 من المادة (101) من هذا القانون . ويجوز الطعن بالاستئناف فى الحكم الصادر بالإيداع تطبيقا للبندين 7 ، 8 وذلك أمام الدائرة الاستئنافية المختصة بنظر الطعون فى قضايا الأطفال ، وفقا للمادة (132) من هذا القانون . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "95", "chapter": "الباب الثامن", "text": "مع مراعاة حكم المادة (111) من هذا القانون ، تسرى الأحكام الواردة فى هذا الباب على من لم تجاوز سنة ثمانى عشرة سنة ميلادية كاملة وقت ارتكاب الجريمة أو عند وجودة فى إحدى حالات التعرض للخطر . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "96", "chapter": "الباب الثامن", "text": "يعد الطفل معرضا للخطر ، إذا وجد فى حالة تهدد سلامة التنشئة الواجب توافرها له ، وذلك فى أى من الأحوال الآتية : 1- إذا تعرض أمنة أو أخلاقة أو صحته أو حياته للخطر . 2- إذا كانت ظروف تربيته فى الأسرة أو المدرسة أو مؤسسات الرعاية أو غيرها من شأنها أن تعرضه للخطر أو كان معرضا للإهمال أو للإساءة أو العنف أو الاستغلال أو التشرد . 3- إذا حرم الطفل ، بغير مسوغ ، من حقه ولو بصفة جزئية فى حضانة أو رؤية أحد والديه أو من له الحق فى ذلك . 4- إذا تخلى عنة الملتزم بالإنفاق علية أو تعرض لفقد والديه أو أحدهما أو تخليهما أو متولى أمره عن المسئولية قبله . 5- إذا حرم الطفل من التعليم الأساسى أو تعرض مستقبله التعليمى للخطر . 6- إذا تعرض داخل الأسرة أو المدرسة أو مؤسسات الرعاية أو غيرها للتحريض على العنف أو الأعمال المنافية للآداب أو الأعمال الإباحية أو الاستغلال التجارى أو التحرش أو الاستغلال الجنسى أو الاستعمال غير المشروع للكحوليات أو المواد المخدرة المؤثرة على الحالة العقلية . 7- إذا وجد متسولا ، ويعد من أعمال التسول عرض سلع أو خدمات تافهة أو القيام بألعاب بهلوانية وغير ذلك مما لا يصلح موردا جديا للعيش . 8- إذا مارس جمع أعقاب السجاير أو غيرها من الفضلات والمهملات . 9- إذا لم يكن له محل إقامة مستقر أو كان يبيت عادة فى الطرقات أو فى أماكن أخرى غير معدة للإقامة أو المبيت . 10- إذا خالط المنحرفين أو المشتبه فيهم أو الذين اشتهر عنهم سوء السيرة . 11- إذا كان سىء السلوك ومارقا من سلطة أبيه أو وليه أو وصيه أو متولى أمره ، أو من سلطة أمه فى حالة وفاة وليه أو غيابه أو عدم أهليته . ولا يجوز فى هذه الحالة اتخاذ أى إجراء قبل الطفل ، ولو كان من إجراءات الاستدلال، إلا بناء على شكوى من أبيه أو وليه أو وصيه أو أمه أو متولى أمره بحسب الأحوال . 12- إذا لم يكن للطفل وسيلة مشروعة للتعيش ولا عائل مؤتمن . 13- إذا كان مصابا بمرض بدنى أو عقلى أو نفسى أو ضعف عقلى وذلك على نحو يؤثر فى قدرته على الإدراك أو الاختيار بحيث يخشى من هذا المرض أو الضعف على سلامته أو سلامة الغير . 14- إذا كان الطفل دون سن السابعة وصدرت منه واقعة تشكل جناية أو جنحة . وفيما عدا الحالات المنصوص عليها فى البندين (3) و (4) ، يعاقب كل من عرض طفلا لإحدى حالات الخطر بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن ألفى جنية ولا تجاوز خمسة آلاف جنية أو بإحدى هاتين العقوبتين . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "97", "chapter": "الباب الثامن", "text": "تنشأ بكل محافظة لجنة عامة لحماية الطفولة ، برئاسة المحافظ وعضوية مديرى مديريات الأمن والمختصة بالشئون الاجتماعية والتعليم والصحة وممثل عن مؤسسات المجتمع المدنى المعنية بشئون الطفولة ومن يرى المحافظ الاستعانة به ، ويصدر بتشكيل اللجنة قرار من المحافظ . وتختص هذه اللجنة برسم السياسة العامة لحماية الطفولة فى المحافظة ومتابعة تنفيذ هذه السياسة . وتشكل فى دائرة كل قسم أو مركز شرطة لجنة فرعية لحماية الطفولة ، يصدر بتشكيلها قرار من اللجنة العامة ، ويراعى فى التشكيل أن تضم عناصر أمنية واجتماعية ونفسية وطبية وتعليمية ، على ألا يقل عدد أعضائها عن خمسة ولا يجاوز سبعة أعضاء بما فيهم الرئيس ، ويجوز أن تضم اللجنة بين أعضائها ممثلا أو أكثر لمؤسسات المجتمع المدنى المعنية بشئون الطفولة . وتختص لجان حماية الطفولة الفرعية بمهمة رصد جميع حالات التعرض للخطر والتدخل الوقائى والعلاجى اللازم لجميع هذه الحالات ومتابعة ما يتخذ من إجراءات . مع مراعاة حكم المادة (144) من هذا القانون ينشأ بالمجلس القومى للطفولة والأمومة إدارة عامة لنجدة الطفل ، تختص بتلقى الشكاوى من الأطفال والبالغين ، ومعالجتها بما يحقق سرعة إنقاذ الطفل من كل عنف أو خطر أو إهمال ، وتضم الإدارة فى عضويتها ممثلين لوزارات العدل والداخلية والتضامن الاجتماعى والتنمية المحلية يختارهم الوزراء المختصون، وممثلين لمؤسسات المجتمع المدنى يختارهم الأمين العام للمجلس، ومن يرى الأمين العام الاستعانة بهم . ولإدارة نجدة الطفل صلاحيات طلب التحقيق فيما يرد إليها من بلاغات ، ومتابعة نتائج التحقيقات ، وإرسال تقارير بما يتكشف لها إلى جهات الاختصاص . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "98", "chapter": "الباب الثامن", "text": "إذا وجد الطفل فى إحدى حالات التعرض للخطر المنصوص عليها فى البندين (1) و(2) والبنود من (5) إلى (14) من المادة (96) من هذا القانون ، عرض أمره على اللجنة الفرعية لحماية الطفولة لإعمال شؤونها المنصوص عليها فى المادة (99 مكررا) من هذا القانون وللجنة ، إذا رأت لذلك مقتضى ، أن تطلب من نيابة الطفل إنذار متولى أمر الطفل كتابة لتلافى أسباب تعرضه للخطر ، ويجوز الاعتراض على هذا الإنذار أمام محكمة الطفل خلال عشرة أيام من تاريخ تسلمه ، ويتبع فى نظر هذا الاعتراض والفصل فيه الإجراءات المقررة للاعتراض فى الأوامر الجنائية ويكون الحكم فيه نهائيا . وإذا وجد الطفل فى إحدى حالات التعرض للخطر المشار إليها فى الفقرة السابقة ، بعد صيرورة الإنذار نهائيا ، عرض أمره على اللجنة الفرعية لحماية الطفولة ، وللجنة ، فضلا عن السلطات المقررة لها فى الفقرة السابقة ، عرض أمر الطفل على نيابة الطفل ليتخذ فى شأنه أحد التدابير المنصوص عليها فى المادة (101) من هذا القانون، فإذا كان الطفل لم يبلغ السابعة من عمره فلا يتخذ فى شأنه إلا تدبيرا التسليم أو الإيداع فى إحدى المستشفيات المتخصصة . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "98 مكرر", "chapter": "الباب الثامن", "text": "على كل من علم بتعرض الطفل للخطر أن يقدم إلية ما فى مكنته من المساعدة العاجلة الكفيلة بتوقى الخطر أو زواله عنه . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "99", "chapter": "الباب الثامن", "text": "يكون للجان حماية الطفولة الفرعية تلقى الشكاوى عن حالات تعرض الطفل للخطر ، ولها فى هذه الحالة – بعد التحقق من جدية الشكوى – استدعاء الطفل أو أبويه أو متولى أمره أو المسئول عنه والاستماع إلى أقوالهم حول الوقائع موضوع الشكوى . وعلى اللجنة فحص الشكوى والعمل على إزالة أسبابها ، فإذا عجزت عن ذلك ، رفعت تقريرا بالواقعة وما تم فيها من إجراءات إلى اللجنة العامة لحماية الطفولة ، لتتخذ ما يلزم من إجراءات قانونية . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "99 مكرر", "chapter": "الباب الثامن", "text": "تقوم اللجان الفرعية لحماية الطفولة باتخاذ ما تراه من التدابير والإجراءات الآتية : 1- إبقاء الطفل فى عائلته مع التزام الأبوين باتخاذ الإجراءات اللازمة لرفع الخطر المحدق به وذلك فى آجال محددة ورهن رقابة دورية من لجنة حماية الطفولة . 2- إبقاء الطفل فى عائلته مع تنظيم طرق التدخل الاجتماعى من الجهة المعنية بتقديم الخدمات الاجتماعية والتربوية والصحية اللازمة للطفل وعائلتة ومساعدتها . 3- إبقاء الطفل فى عائلتة مع أخذ الاحتياطات اللازمة لمنع كل اتصال بينة وبين الأشخاص الذين من شأنهم أن يتسببوا له فيما يهدد صحته أو سلامته البدنيه أو المعنوية . 4- التوصية لدى المحكمة المختصة بإيداع الطفل مؤقتا لحين زوال الخطر عنه لدى عائلة أو هيئة أو مؤسسة اجتماعية أو تربوية أخرى وعند الاقتضاء بمؤسسة صحية أو علاجية وذلك طبقا للإجراءات المقررة قانونا . 5- التوصية لدى المحكمة المختصة باتخاذ التدابير العاجلة اللازمة لوضع الطفل فى إحدى مؤسسات الاستقبال أو إعادة التأهيل أو المؤسسات العلاجية أو لدى عائلة مؤتمنة أو هيئة أو مؤسسة اجتماعية أو تعليمية ملائمة للمدة اللازمة لزوال الخطر عنه، وذلك فى حالات تعرض الطفل للخطر أو إهماله من قبل الأبوين أو متولى أمره . 6- وللجنة عند الاقتضاء ، أن ترفع الأمر إلى محكمة الأسرة للنظر فى إلزام المسئول عن الطفل بنفقة وقتية، ويكون قرار المحكمة فى ذلك واجب التنفيذ ولا يوقفه الطعن فيه . وفى حالات الخطر المحدق تقوم الإدارة العامة لنجدة الطفل بالمجلس القومى للطفولة والأمومة أو لجنة حماية أيهما أقرب باتخاذ ما يلزم من إجراءات عاجلة لإخراج الطفل من المكان الذى يتعرض فيه للخطر ونقلة إلى مكان آمن بما فى ذلك الاستعانة برجال السلطة عند الاقتضاء . ويعتبر خطرا محدقا كل عمل إيجابى أو سلبى يهدد حياة الطفل أو سلامته البدنية أو المعنوية على نحو لا يمكن تلافيه بمرور الوقت . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "99 مكرر(1", "chapter": "الباب الثامن", "text": "تقوم لجان حماية الطفولة بصفة دورية بمتابعة إجراءات ونتائج تنفيذ التدابير المتخذة فى شأن الطفل ، ولها أن توصى ، عند الاقتضاء ، بإعادة النظر فى هذه التدابير وتبديلها أو وقفها بما يحقق قدر الإمكان إبقاء الطفل فى محيطه العائلى، وعدم فصله عنة إلا كملاذ أخير ، ولأقصر فترة زمنية ممكنة ، وإعادته إليه فى أقرب وقت . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "100", "chapter": "الباب الثامن", "text": "وإذا وقع الفعل المكون للجريمة تحت تأثير مرض عقلى أو نفسى أو ضعف عقلى أفقد الطفل القدرة على الإدراك أو الاختيار أو كان وقت الجريمة مصاباً بحالة مرضية أضعفت على نحو جسيم إدراكه أو حرية اختياره ، حكم بإيداعه أحد المستشفيات أو المؤسسات المتخصصة. ويتخذ هذا التدبير وفقاً للأوضاع المقررة فى القانون بالنسبة إلى من يصاب بإحدى هذه الحالات أثناء التحقيق أو بعد صدور الحكم."}, {"number": "101", "chapter": "الباب الثامن", "text": "يحكم على الطفل الذى لم تجاوز سنه خمس عشرة سنة ميلادية كاملة ، إذا ارتكب جريمة ، بأحد التدابير الآتية : 1- التوبيخ . 2- التسليم . 3- الإلحاق بالتدريب والتأهيل . 4- الإلزام بواجبات معينة . 5- الاختبار القضائى . 6- العمل للمنفعة العامة بما لا يضر بصحة الطفل أو نفسيته ، وتحدد اللائحة التنفيذية لهذا القانون أنواع هذا العمل وضوابطها . 7- الإيداع فى إحدى المستشفيات المتخصصة . 8- الإيداع فى إحدى مؤسسات الرعاية الاجتماعية . وعدا المصادرة وإغلاق المحال ورد الشىء إلى أصله لا يحكم على هذا الطفل بأى عقوبة أو تدبير منصوص علية فى قانون آخر . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "102", "chapter": "الباب الثامن", "text": "التوبيخ هو توجيه المحكمة اللوم والتأنيب إلى الطفل على ما صدر منة وتحذيره بألا يعود إلى مثل هذا السلوك مرة أخرى."}, {"number": "103", "chapter": "الباب الثامن", "text": "يسلم الطفل إلى أحد أبوية أو إلى من له الولاية أو الوصاية عليه ، فإذا لم تتوافر فى أيهم الصلاحية للقيام بتربيته سلم إلى شخص مؤتمن يتعهد بتربيته وحسن سيرة أو إلى أسره موثوق بها يتعهد عائلها بذلك . وإذا كان الطفل ذا مال أو كان له من يلزم بالاتفاق علية فانونا وطلب من حكم بتسليمه إليه تقرير نفقة له وجب على القاضى أن يعين فى حكمة بالتسليم المبلغ الذى يحصل من مال الطفل أو ما يلزم به المسئول عن النفقة وذلك بعد اعلانه بالجلسة المحددة ومواعيد أداء النفقة، ويكون تحصيلها بطريق الحجز الادارى ، ويكون الحكم بتسليم الطفل إلى غير الملتزم بالاتفاق لمدة لا تزيد على ثلاث سنوات ."}, {"number": "104", "chapter": "الباب الثامن", "text": "يكون تدريب الطفل وتأهيله بأن تعهد المحكمة به إلى أحد المراكز المخصصة لذلك أو إلى أحد المصانع أو المتاجر أو المزارع التى تقبل تدريبه وبما يتناسب مع ظروف الطفل ، مدة تحددها المحكمة فى حكمها ، على ألا تزيد مدة بقاء الطفل فى الجهات المشار إليها على ثلاث سنوات ، وذلك بما لا يعيق انتظام الطفل فى التعليم الأساسى . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "105", "chapter": "الباب الثامن", "text": "الإلزام بواجبات معينة يكون بحظر ارتياد أنواع من المحال أو بفرض الحضور فى أوقات محددة أمام أشخاص أو هيئات معينة ، أو بالمواظبة على بعض الاجتماعات التوجيهية ، أو غير ذلك من القيود التى تحدد بقرار من الوزير المختص بالشئون الاجتماعية ، ويكون الحكم بهذا التدبير لمدة لا تقل عن ستة أشهر ولا تزيد على ثلاث سنوات . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "106", "chapter": "الباب الثامن", "text": "يكون الاختبار القضائى بوضع الطفل فى بيئته الطبيعية تحت التوجيه والإشراف ومع مراعاة الواجبات التى تحددها المحكمة ، ولا يجوز أن تزيد مدة الاختبار القضائى على ثلاث سنوات فإذا فشل الطفل فى الاختبار عرض الأمر على المحكمة لتتخذ ما تراه مناسبا من التدابير الأخرى الواردة بالمادة (101) من هذا القانون ."}, {"number": "107", "chapter": "الباب الثامن", "text": "يكون إيداع الطفل فى إحدى مؤسسات الرعاية الاجتماعية للأحداث التابعة للوزارة المختصة بالشئون الاجتماعية أو المعترف بها منها ، فإذا كان الطفل معاقا يكون الإيداع فى معهد مناسب لتأهيله ، ولا تحدد المحكمة فى حكمها مدة للإيداع، ويجب على المحكمة متابعة أمر الحدث عن طريق تقرير تقدمه المؤسسة التى أودع بها الطفل كل شهرين على الأكثر لتقرير المحكمة إنهاء التدبير فورا أو إبداله حسب الاقتضاء على أن تراعى أن يكون الإيداع لأقصر فترة ممكنة ، وفى جميع الأحوال يتعين ألا تقضى المحكمة بتدبير الإيداع إلا كملاذ أخير . وفى جميع الأحوال ، يجب ألا تزيد مدة الإيداع على عشر سنوات فى الجنايات وخمس سنوات فى الجنح . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "108", "chapter": "الباب الثامن", "text": "يلحق المحكوم بإيداعه أحد المستشفيات المتخصصة ، بالجهات التى يلقى فيها العناية التى تدعو إليها حالته . وتتولى المحكمة الرقابة على بقائه تحت العلاج فى فترات دورية لا يجوز أن تزيد أى فترة منها على سنة يعرض عليها خلالها تقارير الأطباء ، وتقرر إخلاء سبيله إذا تبين لها أن حالته تسمح بذلك ، وإذا بلغ الطفل سن الحادية والعشرين وكانت حالته تستدعى استمرار علاجه نقل إلى أحد المستشفيات المخصصة لعلاج الكبار ."}, {"number": "109", "chapter": "الباب الثامن", "text": "إذا ارتكب الطفل الذى لم تجاوز سنه خمس عشرة سنة جريمتين أو أكثر وجب الحكم بتدبير واحد مناسب ، ويتبع ذلك إذا ظهر بعد الحكم بالتدبير أن الطفل ارتكب جريمة أخرى سابقة أو لاحقة على ذلك الحكم . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "110", "chapter": "الباب الثامن", "text": "وينتهى التدبير حتما ببلوغ المحكوم علية ثمانية عشر عاماً ، ومع ذلك يجوز للمحكمة فى مواد الجنايات بناء على طلب النيابة العامة وبعد اخذ رأى المراقب الاجتماعى الحكم بوضع المحكوم عليه تحت الاختبار القضائى ، وذلك لمدة لا تزيد على سنتين ، وإذا كنت حالة المحكوم بإيداعه احد المستشفيات المتخصصة تستدعى استمرار علاجه نقل إلى احد المستشفيات التى تناسب حالته وفقا لما نصت علية المادة (108) من هذا القانون . معدلة بالقانون رقم 7 لسنة 2015"}, {"number": "111", "chapter": "الباب الثامن", "text": "لا يحكم بالإعدام ولا بالسجن المؤبد ولا بالسجن المشدد على المتهم الذى لم يجاوز سنه الثامنة عشرة سنة ميلادية كاملة وقت ارتكاب الجريمة . ومع عدم الإخلال بحكم المادة (17) من قانون العقوبات ، إذا أرتكب الطفل الذى تجاوزت سنة خمس عشرة سنة جريمة عقوبتها الإعدام أو السجن المؤبد أو السجن المشدد يحكم علية بالسجن ، وإذا كانت الجريمة عقوبتها السجن يحكم علية بالحبس مدة لا تقل عن ثلاثة أشهر . ويجوز للمحكمة بدلا من الحكم بعقوبة الحبس أن تحكم علية بالتدبير المنصوص علية فى البند (8) من المادة (101) من هذا القانون . أما إذا ارتكب الطفل الذى تجاوزت سنة خمس عشرة سنة جنحة معاقبا عليها بالحبس جاز للمحكمة ، بدلا من الحكم بالعقوبة المقررة لها ، أن تحكم بأحد التدابير المنصوص عليها فى البنود (5) و (6) و (8) من المادة (101) من هذا القانون . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "112", "chapter": "الباب الثامن", "text": "لا يجوز احتجاز الأطفال أو حبسهم أو سجنهم مع غيرهم من البالغين فى مكان واحد ، ويراعى فى تنفيذ الاحتجاز تصنيف الأطفال بحسب السن والجنس ونوع الجريمة . ويعاقب بالحبس مدة لا تقل عن ثلاثة أشهر ولا تزيد على سنتين وبغرامة لا تقل عن ألف جنية ولا تجاوز خمسة آلاف جنية أو بإحدى هاتين العقوبتين كل موظف عام أو مكلف بخدمة عامة احتجز أو حبس أو سجن طفلا مع بالغ أو أكثر فى مكان واحد . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "113", "chapter": "الباب الثامن", "text": "يعاقب بغرامة لا تجاوز ثلاثمائة جنية من أهمل ، بعد إنذاره طبقا للفقرة الأولى من المادة (98) من هذا القانون ، مراقبة الطفل وترتب على ذلك تعرضه للخطر فى إحدى الحالات المشار إليها فى الفقرة الأولى من المادة (98) من هذا القانون . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "114", "chapter": "الباب الثامن", "text": "يعاقب بغرامة لا تقل عن مائتى جنية ولا تجاوز ألف جنية من سلم إلية طفل وأهمل فى أداء أحد واجباته إذا ترتب على ذلك ارتكاب الطفل جريمة أو تعرضه للخطر فى إحدى الحالات المبينة فى هذا القانون . فإذا كان ذلك ناشئا عن إخلال جسيم بواجباته تكون العقوبة الحبس مدة لا تقل عن ثلاثة أشهر ولا تجاوز سنة وغرامة لا تقل عن ألف جنية ولا تجاوز خمسة آلاف جنية أو بإحدى هاتين العقوبتين ."}, {"number": "115", "chapter": "الباب الثامن", "text": "عدا الأبوين والأجداد والزوج والزوجة يعاقب بالحبس وبغرامة لا تزيد على ألف جنية أو بإحدى هاتين العقوبتين كل من أخفى طفلا حكم بتسليمه لشخص أو جهة طبقا لأحكام هذا القانون أو دفعه للفرار أو ساعده على ذلك. مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "116", "chapter": "الباب الثامن", "text": "مع عدم الإخلال بأحكام المساهمة الجنائية ، يعاقب كل بالغ حرض طفلاً على ارتكاب جنحة أو أعدة لذلك أو ساعده عليها أو سهلها له بأى وجه ولم يبلغ مقصده من ذلك بما لا يجاوز نصف الحد الأقصى للعقوبة المقررة لتلك الجريمة . وتكون العقوبة الحبس مدة لا تقل عن ستة أشهر إذا استعمل الجانى مع الطفل وسائل إكراه أو تهديد أو كان من أصولة أو من المسئولين عن تربيته أو ملاحظته أو كان مسلما إلية بمقتضى القانون ، أو كان خادما عند أى ممن تقدم ذكرهم . وفى جميع الأحوال إذا وقعت الجريمة على أكثر من طفل ، ولو فى أوقات مختلفة ، كانت العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على سبع سنوات . ويعاقب بالعقوبة المقررة للشروع فى الجريمة المحرض عليها ، كل بالغ حرض طفلا على ارتكاب جناية أو أعده لذلك أو ساعده عليها أو سهلها له بأى وجة ولم يبلغ مقصده من ذلك . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "116 مكرر", "chapter": "الباب الثامن", "text": "يزاد بمقدار المثل الحد الأدنى للعقوبة المقررة لأى جريمة إذا وقعت من بالغ على طفل ، أو إذا ارتكبها أحد والدية أو من له الولاية أو الوصاية علية أو المسئول عن ملاحظته وتربيته أو من له سلطة علية ، أو كان خادما عند من تقدم ذكرهم . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "116 مكرر", "chapter": "الباب الثامن", "text": "أ) يعاقب بالحبس مدة لا تقل عن سنتين وبغرامة لا تقل عن عشرة آلاف جنية ولا تجاوز خمسين ألف جنية كل من استورد أو صدر أو أنتج أو أعد أو عرض أو طبع أو روج أو حاز أو بث أى أعمال إباحية يشارك فيها أطفال أو تتعلق بالاستغلال الجنسى للطفل ، ويحكم بمصادرة الأدوات والآلات المستخدمة فى ارتكاب الجريمة والأموال المتحصلة منها ، وغلق الأماكن محل ارتكابها مدة لا تقل عن ستة أشهر ، وذلك كله مع عدم الإخلال بحقوق الغير حسن النية . ومع عدم الإخلال بأى عقوبة أشد ينص عليها فى قانون آخر ، يعاقب بذات العقوبة كل من : (أ)- استخدام الحاسب الآلى أو الإنترنت أو شبكات المعلومات أو الرسوم المتحركة لإعداد أو لحفظ أو لمعالجة أو لعرض أو لطباعة أو لنشر أو لترويج أنشطه أو أعمال إباحية تتعلق بتحريض الأطفال أو استغلالهم فى الدعارة والأعمال الإباحية أو التشهير بهم أو بيعهم . (ب)- استخدام الحاسب الآلى أو الإنترنت أو شبكات المعلومات أو الرسوم المتحركة لتحريض الأطفال على الانحراف أو لتسخيرهم فى ارتكاب جريمة أو على القيام بأنشطة أو أعمال غير مشروعة أو منافية للآداب ، ولو لم تقع الجريمة فعلا . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "116 مكرر", "chapter": "الباب الثامن", "text": "ب) مع عدم الإخلال بأى عقوبة أشد ينص عليها فى قانون آخر، يعاقب بغرامة لا تقل عن عشرة آلاف جنية ولا تجاوز خمسين ألف جنية كل من نشر أو أذاع بأحد أجهزة الإعلام أى معلومات أو بيانات ، أو أى رسوم أو صور تتعلق بهوية الطفل حال عرض أمرة على الجهات المعنية بالأطفال المعرضين للخطر أو المخالفين للقانون . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "116 مكرر", "chapter": "الباب الثامن", "text": "ج) تسرى أحكام انقضاء الدعوى الجنائية بالصلح أو التصالح ، المقررة فى قانون الإجراءات الجنائية أو أى قانون آخر ، على الجرائم التى يرتكبها الطفل . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "116 مكرر", "chapter": "الباب الثامن", "text": "د) يكون للأطفال المجنى عليهم والأطفال الشهود ، فى جميع مراحل الضبط والتحقيق والمحاكمة والتنفيذ ، الحق فى الاستماع إليهم وفى المعاملة بكرامة وإشفاق ، مع الاحترام الكامل لسلامتهم البدنية والنفسية والأخلاقية ، والحق فى الحماية والمساعدة الصحية والاجتماعية والقانونية وإعادة التأهيل والدمج فى المجتمع ، فى ضوء المبادىء التوجيهية للأمم المتحدة بشأن توفير العدالة للأطفال ضحايا الجريمة والشهود عليها . مضافة بالقانون رقم 126 لسنة 2008"}, {"number": "117", "chapter": "الباب الثامن", "text": "يكون للموظفين الذين يعينهم وزير العدل بالاتفاق مع الوزير المختص بالشئون الاجتماعية فى دوائر اختصاصهم سلطة الضبط القضائى فيما يختص بالجرائم التى تقع من الأطفال وحالات تعريضهم للخطر وسائر الجرائم المنصوص عليها فى هذا القانون . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "118", "chapter": "الباب الثامن", "text": "يصدر باختيار المراقبين الاجتماعيين وتحديد الشروط الواجب توافرها فيهم قرار من الوزير المختص الشئون الاجتماعية . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "119", "chapter": "الباب الثامن", "text": "لا يحبس احتياطيا الطفل الذى لم يجاوز خمس عشرة سنة ، ويجوز للنيابة العامة إيداعه إحدى دور الملاحظة مدة لا تزيد على أسبوع وتقديمه عند كل طلب إذا كانت ظروف الدعوى تستدعى التحفظ علية ، على ألا تزيد مدة الإيداع على أسبوع ما لم تأمر المحكمة بمدها وفقا لقواعد الحبس الاحتياطى المنصوص عليها فى قانون الإجراءات الجنائية . ويجوز بدلا من الإجراء المنصوص عليه فى الفقرة السابقة الأمر بتسليم الطفل إلى أحد والديه أو لمن له الولاية علية للمحافظة عليه وتقديمه عند كل طلب ويعاقب على الإخلال بهذا الواجب بغرامة لا تجاوز مائة جنيه. معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "120", "chapter": "الباب الثامن", "text": "تشكل فى مقر كل محافظة محكمة أو أكثر للطفل ويجوز بقرار من وزير العدل إنشاء محاكم للطفل فى غير ذلك فى الأماكن وتحدد دوائر اختصاصها فى قرار إنشائها . وتتولى أعمال النيابة العامة أمام تلك المحاكم نيابات متخصصة للطفل يصدر بإنشائها قرار من وزير العدل . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "121", "chapter": "الباب الثامن", "text": "تشكل محكمة للطفل من ثلاثة قضاه ، ويعاون المحكمة خبيران من الأخصائيين أحدهما على الأقل من النساء ، ويكون حضورهما إجراءات المحاكمة وجوبياً . وعلى الخبيرين أن يقدما تقريرهما للمحكمة بعد بحث ظروف الطفل من جميع الوجوه وذلك قبل أن تصدر المحكمة حكمها . ويعين الخبيران المشار إليهما بقرار من وزير العدل بالاتفاق مع الوزير المختص بالشئون الاجتماعية وتحدد الشروط الواجب توافرها فيمن يعين خبيرا بقرار من الوزير المختص بالشئون الاجتماعية ويكون استئناف الأحكام الصادرة من محكمة الطفل أمام محكمة استئنافية تشكل بكل محكمة ابتدائية من ثلاث قضاه ، اثنان منهما على الأقل بدرجة رئيس محكمة ويراعى حكم الفقرتين السابقتين فى تشكيل هذه المحكمة . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "122", "chapter": "الباب الثامن", "text": "تختص محكمة الطفل دون غيرها بالنظر فى أمر الطفل عند اتهامه فى إحدى الجرائم أو تعرضه للإنحراف ، كما تختص بالفصل فى الجرائم المنصوص عليها فى المواد من 113 أى 116 والمادة 119 من هذا القانون . واستثناء من حكم الفقرة السابقة يكون الاختصاص لمحكمة الجنايات أو محكمة أمن الدولة العليا بحسب الأحوال - بنظر قضايا الجنايات التى يتهم فيها طفل جاوزت سنة خمس عشرة سنة وقت ارتكابه الجريمة متى أسهم فى الجريمة غير طفل واقتضى الأمر رفع الدعوى الجنائية عليه مع الطفل ، وفى هذه الحالة يجب على المحكمة قبل أن تصدر حكمها أن تبحث ظروف الطفل من جميع الوجوه ولها أن تستعين فى ذلك بمن تراه من الخبراء . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "123", "chapter": "الباب الثامن", "text": "يتحدد لاختصاص محكمة الطفل بالمكان الذى وقعت فيه الجريمة أو توافرت فيه إحدى حالات التعرض للإنحراف أو بالمكان الذى ضبط فيه الطفل أو يقيم فيه هو أو ولية أو وصية أو أمة بحسب الأحوال . ويجوز للمحكمة عند الاقتضاء أن تنعقد فى إحدى مؤسسات الرعاية الاجتماعية للأطفال التى يودع فيها الطفل . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "124", "chapter": "الباب الثامن", "text": "يتبع أمام محكمة الطفل فى جميع الأحوال القواعد والإجراءات المقررة فى مواد الجنح ما لم ينص القانون على خلاف ذلك . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "125", "chapter": "الباب الثامن", "text": "للطفل الحق فى المساعدة القانونية ، ويجب أن يكون له فى مواد الجنايات وفى مواد الجنح المعاقب عليها بالحبس وجوبا محام يدافع عنه فى مرحلتى التحقيق والمحاكمة ، فإذا لم يكن قد اختار محاميا تولت النيابة العامة أو المحكمة ندبه، وذلك طبقا للقواعد المقررة فى قانون الإجراءات الجنائية . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "126", "chapter": "الباب الثامن", "text": "لا يجوز أن يحضر محاكمة الطفل أمام محكمة الطفل إلا أقاربه والشهود والمحامون والمراقبون الاجتماعيون ومن تجيز له المحكمة الحضور بإذن خاص . وللمحكمة أن تأمر بإخراج الطفل من الجلسة بعد سؤاله أو بإخراج أحد ممن ذكروا فى الفقرة السابقة إذا رأت ضرورة لذلك على أنة لا يجوز فى حالة إخراج لطفل أن تأمر بإخراج محامية أو المراقب الاجتماعى كما لا يجوز للمحكمة الحكم بالإدانة إلا بعد إفهام الطفل بما تم في غيبته من إجراءات ، وللمحكمة إعفاء الطفل من حضور المحاكمة بنفسه إذا رأت أن مصلحته تقتضى ذلك ، ويكتفى بحضور وليه أو وصيه نيابة عنه وفى هذه الحالة يعتبر الحكم حضورياً . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "127", "chapter": "الباب الثامن", "text": "ينشىء المراقبون المشار إليهم فى المادة (118) من هذا القانون لكل طفل متهم بجناية أو جنحة وقبل التصرف فى الدعوى ملفا يتضمن فحصا كاملا لحالته التعليمية والنفسية والعقلية والبدنية والاجتماعية ويتم التصرف فى الدعوى على ضوء ما ورد فيه . ويجب على المحكمة قبل الحكم فى الدعوى أن تناقش واضعى تقارير الفحص المشار إليها فيما ورد بها ولها أن تأمر بفحوص إضافية . مستبدلة بالقانون رقم 126 لسنة 2008"}, {"number": "128", "chapter": "الباب الثامن", "text": "إذا رأت المحكمة أن حالة الطفل البدنية أو العقلية أو النفسية تستلزم فحصة قبل الفصل فى الدعوى قررت وضعه تحت الملاحظة فى أحد الأماكن المناسبة المدة التى تلزم لذلك ويوقف السير فى الدعوى إلى أن يتم هذا الفحص ."}, {"number": "129", "chapter": "الباب الثامن", "text": "لا تقبل الدعوى المدنية أمام محكمة الطفل . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "130", "chapter": "الباب الثامن", "text": "يكون الحكم الصادر على الطفل بالتدابير واجب التنفيذ ولو كان قابلا للاستئناف."}, {"number": "131", "chapter": "الباب الثامن", "text": "كل إجراء مما يوجب القانون إعلانه إلى الطفل وكل حكم يصدر فى شأنه يبلغ إلى أحد والديه أو من له الولاية عليه أو إلى المسئول عنه ولكل من هؤلاء أن يباشر لمصلحة الطفل طرق الطعن المقررة فى القانون ."}, {"number": "132", "chapter": "الباب الثامن", "text": "يجوز استئناف الأحكام الصادرة من محكمة الطفل عدا الأحكام التى تصدر بالتوبيخ وبتسليم الطفل لوالديه أو لمن له الولاية علية فلا يجوز استئنافها إلا لخطأ فى تطبيق القانون أو بطلان فى الحكم أو فى الإجراءات أثر فيه . ويرفع الاستئناف أمام دائرة تخصص لذلك فى المحكمة الابتدائية . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "133", "chapter": "الباب الثامن", "text": "إذا حكم على متهم بعقوبة باعتبار أن سنة تجاوزت الخامسة عشرة ثم ثبت بأوراق رسمية أنة لم يجاوزها رفع المحامى العام الأمر إلى المحكمة التى أصدرت الحكم لإعادة النظر فيه وفقا للقانون ، وإذا حكم على المتهم باعتبار أن سنه تجاوزت الثامنة عشرة ثم ثبت بأوراق رسمية أنه لم يجاوزها رفع المحامى العام الأمر إلى المحكمة التى أصدرت الحكم لإعادة النظر فيه والقضاء بإلغاء حكمها وإحالة الأوراق إلى النيابة العامة للتصرف . وفى الحالتين السابقتين يوقف تنفيذ الحكم ويجوز التحفظ على المحكوم علية طبقا للمادة (19) من هذا القانون . وإذا حكم على متهم باعتباره طفلا ، ثم ثبت بأوراق رسمية أنة تجاوز الثامنة عشرة يجوز للمحامى العام أن يرفع الأمر إلى المحكمة التى أصدرت الحكم لتعيد النظر فيه على النحو المبين فى الفقرتين السابقتين . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "134", "chapter": "الباب الثامن", "text": "يختص رئيس محكمة الطفل التى يجرى التنفيذ فى دائرتها دون غيره بالفصل فى جميع المنازعات وإصدار القرارات والأوامر المتعلقة بتنفيذ الأحكام الصادرة على أن يتقيد فى الفصل فى الأشكال فى التنفيذ بالقواعد المنصوص عليها فى قانون الإجراءات الجنائية . ويقوم رئيس محكمة الطفل أو من يندبه من قضاة المحكمة أو خبير بها بزيارة دور الملاحظة ومراكز التدريب والتأهيل ومؤسسات الرعاية الاجتماعية والمستشفيات المتخصصة والمؤسسات العقابية وغير ذلك من الجهات التى تتعاون مع محكمة الطفل والواقعة فى دائرة اختصاصها وذلك مرة على الأقل كل ثلاثة أشهر ، للتحقق من قيامها بواجباتها فى إعادة تأهيل الطفل ومساعدته لإعادة إدماجه فى المجتمع ، ولرئيس محكمة الطفل إرسال تقرير بملاحظاته إلى اللجنة العامة لحماية الطفولة المختصة لإعمال مقتضاه. معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "135", "chapter": "الباب الثامن", "text": "فيما عدا تدبير التوبيخ يتولى المراقب الاجتماعى الإشراف على تنفيذ التدابير المنصوص عليها فى المواد من (101) إلى (104) من هذا القانون وملاحظة المحكوم علية بها وتقديم التوجيهات له وللقائمين على تربيته وعلية أن يرفع إلى محكمة الطفل تقارير دورية عن الطفل الذى يتولى أمره والإشراف عليه . وعلى المسئول عن الطفل إخبار المراقب الاجتماعى فى حالة موت الطفل أو مرضه أو تغيير سكنه أو غيابه دون إذن وكذلك عن كل طارىء آخر يطرأ عليه . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "136", "chapter": "الباب الثامن", "text": "إذا خالف الطفل حكم التدبير المفروض علية بمقتضى إحدى المواد (104) و (105) و (106) من هذا القانون فللمحكمة أن تأمر بعد سماع أقواله بإطالة مدة التدبير بما لا يجاوز نصف الحد الأقصى المقرر بالمواد المشار إليها أو أن تستبدل به تدبيراً آخر يتفق مع حالته."}, {"number": "137", "chapter": "الباب الثامن", "text": "للمحكمة فيما عدا التدبير المنصوص علية فى المادة (102) من هذا القانون أن تأمر بعد إطلاعها على التقارير المقدمة إليها أو بناء على طلب النيابة العامة أو الطفل أو من له الولاية أو الوصاية عليه أو من سلم إليه ، بإنهاء التدبير أو بتعديل نظامه أو بإبداله مع مراعاة حكم المادة (110) من هذا القانون وإذا رفض هذا الطلب فلا يجوز تجديده إلا بعد مرور ثلاثة أشهر على الأقل من تاريخ رفضه ويكون الحكم الصادر فى هذا الشأن غير قابل للطعن ."}, {"number": "138", "chapter": "الباب الثامن", "text": "لا ينفذ أى تدبير أغفل تنفيذه سنة كاملة من يوم النطق به إلا بقرار يصدر من المحكمة بناء على طلب النيابة العامة بعد أخذ رأى المراقب الاجتماعى ."}, {"number": "139", "chapter": "الباب الثامن", "text": "لا يجوز التنفيذ بطريق الإكراه البدنى على المحكوم عليهم الخاضعين لأحكام هذا القانون الذين لم يتجاوزوا من العمر ثمانى عشرة سنة كاملة وقت التنفيذ . معدلة بالقانون رقم 126 لسنة 2008"}, {"number": "140", "chapter": "الباب الثامن", "text": "لا يلزم الأطفال بأداء أى رسوم أو مصاريف أمام جميع المحاكم فى الدعاوى المتعلقة بهذا الباب ."}, {"number": "141", "chapter": "الباب الثامن", "text": "يكون تنفيذ العقوبات المقيدة للحرية المحكوم بها على الأطفال فى مؤسسات عقابية خاصة يصدر بتنظيمها قرار من وزير الشئون الاجتماعية بالاتفاق مع وزير الداخلية . فإذا بلغ سن الطفل ثمانية عشر عاماً تنفذ علية العقوبة أو المدة الباقية منها فى أحد السجون العمومية ، ويجوز مع ذلك استمرار التنفيذ علية فى المؤسسة العقابية إذا لم يكن هناك خطورة من ذلك وكانت المدة الباقية من العقوبة لا تجاوز ستة أشهر . معدلة بالقانون رقم 7 لسنة 2015"}, {"number": "142", "chapter": "الباب الثامن", "text": "ينشأ لكل طفل محكوم عليه ملف تنفيذ يضم إليه ملف الموضوع تودع فيه جميع الأوراق المتعلقة بتنفيذ الحكم الصادر علية ويثبت فيه ما يصدر فى شأن التنفيذ من قرارات وأوامر وأحكام ، ويعرض هذا الملف على رئيس المحكمة قبل اتخاذ أى إجراء من الإجراءات المنصوص عليها فى المادة (134) من هذا القانون."}, {"number": "143", "chapter": "الباب الثامن", "text": "تطبق الأحكام الواردة فى قانون العقوبات وقانون الإجراءات الجنائية فيما لم يرد به نص فى هذا الباب ."}, {"number": "144", "chapter": "الباب التاسع", "text": "ينشأ مجلس يسمى ( المجلس القومى للطفولة والأمومة ) تكون له الشخصية الاعتبارية ومقره مدينة القاهرة ، ويصدر بتشكيله وتنظيمه وتحديد اختصاصاته قرار من رئيس الجمهورية ."}, {"number": "144 مكرر", "chapter": "الباب التاسع", "text": "ينشأ صندوق يتبع المجلس القومى للطفولة والأمومة يسمى صندوق رعاية الطفولة والأمومة وتكون له الشخصية الاعتبارية المستقلة وموازنة خاصة ، وتبدأ السنة المالية له ببداية السنة المالية للدولة وتنتهى بنهايتها ، ويرحل فائض الحساب من سنة مالية إلى أخرى . مضافة بالقانون رقم 126 لسنة 2008."}, {"number": "144 مكرر", "chapter": "الباب التاسع", "text": "أ) : يكون للصندوق مجلس إدارة برئاسة الأمين العام للمجلس القومى للطفولة والأمومة ، ويصدر بتشكيل مجلس إدارة الصندوق ونظام العمل فيه قرار من رئيس مجلس الوزراء ، وتكون مدة مجلس إدارة الصندوق ثلاث سنوات قابلة للتجديد . مضافة بالقانون رقم 126 لسنة 2008."}, {"number": "144 مكرر", "chapter": "الباب التاسع", "text": "ب): مجلس إدارة الصندوق هو الجهة المهيمنة على شئونه ، وله على وجه الخصوص ما يأتى : 1- اتخاذ ما يلزم لتنمية موارد الصندوق . 2- إنشاء دور إيواء ومدارس ومستشفيات خاصة بالطفل . 3- إقامة مشروعات خدمية وإنتاجية وحفلات وأسواق خيرية ومعارض ومباريات رياضية لتحقيق أهداف المجلس القومى للطفولة والأمومة ، وذلك بعد الحصول على التصريح من الجهات المعنية . 4- توزيع إعانات على الجهات المهتمة بالطفولة والأمومة . 5- القيام بأى عمل من شأنه دعم حقوق الطفل . مضافة بالقانون رقم 126 لسنة 2008."}, {"number": "144 مكرر", "chapter": "الباب التاسع", "text": "ج) : تتكون موارد الصندوق مما يأتى : (أ)- المبالغ المدرجة بالموازنة العامة للدولة لدعم الصندوق . (ب)- الغرامات ومقابل التصالح عن الجرائم المنصوص عليها فى هذا القانون . (ج)- عوائد استثمار أموال الصندوق والعقارات التى تخصص له أو تؤول إلية . (د)- الهبات والإعانات والتبرعات والوصايا التى يقرر مجلس إدارة الصندوق قبولها، وتعفى هذه الهبات والإعانات والتبرعات والوصايا من جميع أنواع الضرائب . مضافة بالقانون رقم 126 لسنة 2008."}]};